-- RN Master standalone MC/SATA pilot import. Source: user-provided 1000-question RN master bank.
begin;
do $$
declare r record; qid uuid; qvid uuid; optrec record; n int; keyarr text[]; kc int;
begin
for r in select * from (values
('Set04-RN-1','Management of Care','Prioritization','single_best_answer','The nurse receives report on four clients. Which client should the nurse assess first?','A client 6 hours after transsphenoidal hypophysectomy who has had 900 mL of urine output in the past 2 hours|A client with hypothyroidism who reports constipation|A client with Cushing''s syndrome who is asking about weight-loss options|A client with type 2 diabetes whose pre-lunch glucose is 182 mg/dL','A','Large-volume urine output after pituitary surgery suggests diabetes insipidus, which can rapidly cause hypovolemia and hypernatremia. The other clients have stable, chronic concerns.','Endocrine','Management of Care'),
('Set04-RN-2','Pharmacological and Parenteral Therapies','Insulin administration','single_best_answer','The nurse is preparing to mix regular insulin and NPH insulin in one syringe. Which sequence is correct?','Draw up NPH first, then regular|Inject air into the NPH vial, inject air into the regular vial, draw up regular, then draw up NPH|Draw up regular insulin, then inject it into the NPH vial and mix|Draw up both insulins in separate syringes and combine them in a third syringe','B','Clear (regular) is drawn before cloudy (NPH) to avoid contaminating the regular vial with NPH. Air is injected into both vials first, starting with NPH.','Endocrine','Pharmacology'),
('Set04-RN-3','Pharmacological and Parenteral Therapies','Insulin action','single_best_answer','A client receives NPH insulin at 0700. At what time is the client at greatest risk for hypoglycemia?','0730–0800|0900–1000|1100–1900|0200–0400 the next morning','C','NPH (intermediate-acting) peaks about 4–12 hours after injection, so a morning dose places the client at risk from late morning to early evening. The client should not skip lunch or the afternoon snack.','Endocrine','Pharmacology'),
('Set04-RN-4','Physiological Adaptation','Hypoglycemia','single_best_answer','A client with diabetes reports feeling shaky and sweaty. The fingerstick glucose is 58 mg/dL, and the client is alert and able to swallow. What should the nurse do first?','Give 4 oz (120 mL) of fruit juice and recheck the glucose in 15 minutes|Administer glucagon 1 mg IM|Give a peanut butter sandwich and a glass of milk|Notify the provider and wait for prescriptions','A','The 15-15 rule: give 15 g of fast-acting carbohydrate, recheck in 15 minutes, and repeat if the glucose is still below 70 mg/dL. A snack with protein follows once the glucose recovers. Glucagon is for clients who cannot safely swallow.','Endocrine','Adult Health'),
('Set04-RN-5','Pharmacological and Parenteral Therapies','Severe hypoglycemia','single_best_answer','A client with type 1 diabetes is found unresponsive in the bathroom. The fingerstick glucose is 32 mg/dL, and the client does not have IV access. Which action is most appropriate?','Place glucose gel inside the client''s cheek|Administer glucagon IM, subcutaneously, or intranasally|Give 4 oz of orange juice through a straw|Administer regular insulin subcutaneously','B','Glucagon stimulates hepatic glycogen release and can be given without IV access. Nothing is given by mouth to an unresponsive client because of aspiration risk. Once IV access is available, dextrose 50% is an alternative. The client is placed on their side because glucagon can cause vomiting.','Endocrine','Pharmacology'),
('Set04-RN-6','Health Promotion and Maintenance','Sick-day management','multiple_response','The nurse is teaching a client with type 1 diabetes about sick-day management. Which instructions should the nurse include? Select all that apply. ☐','Continue taking insulin even if you cannot eat ☐|Check your blood glucose every 2–4 hours ☐|Check urine or blood ketones if your glucose is above 240 mg/dL ☐|Drink 8–12 oz (240–360 mL) of sugar-free fluid every hour while awake ☐|Stop taking insulin until you can eat solid food again ☐|Call your provider if you are vomiting and cannot keep fluids down','A,B,C,D,F','Illness raises glucose through stress hormones, so insulin must continue even without eating. Frequent monitoring, ketone checks, and hydration prevent DKA. Persistent vomiting requires medical attention. Stopping insulin is a common cause of DKA.','Endocrine','Fundamentals'),
('Set04-RN-7','Pharmacological and Parenteral Therapies','Metformin','single_best_answer','A client taking metformin is scheduled for a CT scan with IV iodinated contrast. What does the nurse anticipate?','Doubling the metformin dose the day before the scan|Holding metformin at the time of or before the procedure and for 48 hours afterward, until renal function is confirmed|Giving metformin with the contrast to prevent hyperglycemia|No change to metformin','B','Contrast can cause acute kidney injury, which impairs metformin clearance and increases the risk of lactic acidosis. Metformin is typically held and resumed once renal function is stable, per facility protocol.','Endocrine','Pharmacology'),
('Set04-RN-8','Physiological Adaptation','Hyperosmolar hyperglycemic state','single_best_answer','An 80-year-old client with type 2 diabetes is admitted with confusion and severe dehydration. Which finding best distinguishes hyperosmolar hyperglycemic state (HHS) from diabetic ketoacidosis?','Blood glucose of 320 mg/dL|Kussmaul respirations|Blood glucose of 960 mg/dL with minimal or no ketones and serum osmolality of 350 mOsm/kg|Arterial pH of 7.10','C','HHS features extreme hyperglycemia and hyperosmolality without significant ketoacidosis, because enough insulin is present to prevent ketogenesis. Kussmaul respirations and a low pH indicate DKA.','Endocrine','Adult Health'),
('Set04-RN-9','Physiological Adaptation','Thyroid storm','single_best_answer','A client with Graves'' disease is 12 hours postoperative after a thyroidectomy. Which finding requires immediate action by the nurse?','Incisional pain rated 4 on a 0–10 scale|Temperature of 104°F (40°C), HR 152/min, and agitation|Mild hoarseness|Serosanguineous drainage on the dressing','B','Hyperthermia, marked tachycardia, and agitation indicate thyroid storm, a life-threatening emergency. Mild hoarseness from edema or intubation and small amounts of drainage are expected.','Endocrine','Adult Health'),
('Set04-RN-10','Pharmacological and Parenteral Therapies','Levothyroxine','single_best_answer','The nurse is teaching a client who is starting levothyroxine. Which instruction should the nurse include?','"Take it at bedtime with a snack."|"Take it on an empty stomach 30–60 minutes before breakfast."|"Take it with your calcium supplement to improve absorption."|"You can stop taking it once you feel better."','B','Levothyroxine is absorbed best on an empty stomach. Calcium, iron, and antacids reduce absorption and should be separated by about 4 hours. Therapy is usually lifelong, and the client should report palpitations or chest pain, which suggest excess dosing.','Endocrine','Pharmacology'),
('Set04-RN-11','Physiological Adaptation','Myxedema coma','single_best_answer','An older adult with untreated hypothyroidism is admitted with a temperature of 94.2°F (34.6°C), HR 46/min, RR 8/min, and lethargy. What is the nurse''s priority?','Rapid rewarming with a heating blanket|Supporting airway and ventilation|Administering oral levothyroxine|Providing a high-fiber diet','B','Myxedema coma causes hypoventilation and CO2 retention, so airway and breathing come first. IV levothyroxine is given, and rewarming is gradual with blankets because rapid external warming can cause vasodilation and cardiovascular collapse.','Endocrine','Adult Health'),
('Set04-RN-12','Physiological Adaptation','Adrenal crisis','single_best_answer','A client with Addison''s disease is admitted with severe vomiting, BP 78/40 mm Hg, sodium 126 mEq/L, potassium 6.1 mEq/L, and glucose 58 mg/dL. Which treatment does the nurse anticipate first?','IV hydrocortisone and 0.9% sodium chloride|Oral fludrocortisone|IV potassium chloride|Fluid restriction','A','Adrenal crisis requires immediate IV glucocorticoid replacement and volume resuscitation with isotonic saline (with dextrose for hypoglycemia). Potassium is already high. Oral fludrocortisone is for long-term maintenance.','Endocrine','Adult Health'),
('Set04-RN-13','Physiological Adaptation','Cushing''s syndrome','multiple_response','The nurse is assessing a client with Cushing''s syndrome. Which findings does the nurse expect? Select all that apply. ☐','Rounded, moon-shaped face ☐|Purple striae on the abdomen ☐|Hyperglycemia ☐|Hyperkalemia ☐|Fat pad between the shoulders ☐|Hypertension ☐|Hypotension','A,B,C,E,F','Excess cortisol causes fat redistribution (moon face, buffalo hump), fragile skin with striae, hyperglycemia, and hypertension from sodium and water retention. Cortisol excess causes hypokalemia, not hyperkalemia.','Endocrine','Adult Health'),
('Set04-RN-14','Pharmacological and Parenteral Therapies','Corticosteroids','single_best_answer','A client has been taking prednisone 20 mg daily for 6 months. Which client statement indicates a need for further teaching?','"I''ll take my dose in the morning with food."|"I''ll stop taking the prednisone as soon as my symptoms are gone."|"I''ll check my blood sugar as instructed."|"I''ll avoid people who are sick."','B','Long-term steroids suppress the hypothalamic-pituitary-adrenal axis. Stopping abruptly can cause adrenal crisis, so the dose must be tapered as prescribed.','Endocrine','Pharmacology'),
('Set04-RN-15','Physiological Adaptation','SIADH','multiple_response','A client with small cell lung cancer is diagnosed with the syndrome of inappropriate antidiuretic hormone (SIADH). The serum sodium is 121 mEq/L. Which interventions should the nurse anticipate? Select all that apply. ☐','Restrict fluids as prescribed ☐|Implement seizure precautions ☐|Weigh the client daily ☐|Administer 5% dextrose in water at 150 mL/hr ☐|Monitor serum sodium closely ☐|Encourage 3 L of oral fluid daily','A,B,C,E','SIADH causes water retention and dilutional hyponatremia, which increases seizure risk. Fluid restriction, daily weights, and frequent sodium checks are standard. Hypotonic fluids and increased water intake worsen hyponatremia. Sodium must be corrected slowly to prevent osmotic demyelination.','Endocrine','Adult Health'),
('Set04-RN-16','Pharmacological and Parenteral Therapies','Diabetes insipidus','single_best_answer','A client with central diabetes insipidus is started on desmopressin. Which finding indicates the medication is effective?','Urine specific gravity decreases from 1.004 to 1.001|Urine output decreases and urine specific gravity increases to 1.015|Serum sodium increases from 148 to 154 mEq/L|The client reports increased thirst','B','Desmopressin replaces ADH, so the kidneys reabsorb water and produce less, more concentrated urine. A rising sodium and increased thirst indicate continued water loss.','Endocrine','Pharmacology'),
('Set04-RN-17','Reduction of Risk Potential','Pheochromocytoma','single_best_answer','A client is admitted for evaluation of suspected pheochromocytoma. Which action should the nurse avoid?','Monitoring blood pressure frequently|Palpating the abdomen deeply|Collecting a 24-hour urine specimen for metanephrines|Providing a calm, quiet environment','B','Abdominal palpation can stimulate the tumor to release catecholamines and trigger a hypertensive crisis. Frequent BP monitoring and urine metanephrine testing are part of the workup.','Endocrine','Adult Health'),
('Set04-RN-18','Physiological Adaptation','Hyperparathyroidism','single_best_answer','A client with primary hyperparathyroidism has a serum calcium of 12.4 mg/dL. Which intervention should the nurse include?','Encourage oral fluids of 2,000–3,000 mL/day unless contraindicated|Restrict fluids to 1,000 mL/day|Encourage bed rest|Provide a high-calcium diet','A','Hypercalcemia increases the risk of kidney stones and dehydration. Generous fluids dilute urine and promote calcium excretion. Weight-bearing activity helps limit bone calcium loss, while immobility worsens it.','Endocrine','Adult Health'),
('Set04-RN-19','Pharmacological and Parenteral Therapies','GLP-1 receptor agonists','single_best_answer','A client with type 2 diabetes is starting weekly semaglutide injections. Which symptom should the nurse instruct the client to report immediately?','Mild nausea during the first few weeks|Decreased appetite|Severe, persistent abdominal pain radiating to the back|Feeling full sooner at meals Case study (use for RN Questions 20–25). A 19-year-old college student with type 1 diabetes is brought to the emergency department by a roommate. The client has had vomiting and body aches for 2 days and stopped taking insulin "because I wasn''t eating anything." Nurses'' notes, 2200: Lethargic but arousable and oriented. Deep, rapid respirations. Fruity odor on the breath. Dry mucous membranes and poor skin turgor. Reports frequent urination and extreme thirst for 2 days. Abdominal pain rated 6/10. Vital signs: T 99.8°F (37.7°C), HR 124/min, RR 32/min and deep, BP 94/56 mm Hg, SpO2 99% on room air. Laboratory results: glucose 486 mg/dL, arterial pH 7.18, PaCO2 24 mm Hg, HCO3 10 mEq/L, potassium 5.6 mEq/L (3.5–5.0), sodium 131 mEq/L (135–145), anion gap 24 (8–12), serum beta-hydroxybutyrate elevated, BUN 32 mg/dL (7–20), creatinine 1.4 mg/dL (0.6–1.2).','C','Severe abdominal pain radiating to the back can indicate pancreatitis, a serious adverse effect of GLP-1 agonists. Mild nausea, reduced appetite, and early fullness are expected effects.','Endocrine','Pharmacology'),
('Set05-RN-1','Management of Care','Prioritization','single_best_answer','The nurse receives report on four clients. Which client should the nurse assess first?','A client with chronic kidney disease whose potassium is 6.8 mEq/L with peaked T waves on the monitor|A client with a urinary tract infection who reports burning on urination|A client 1 day after a transurethral resection of the prostate with light pink urine during continuous bladder irrigation|A client with a kidney stone who rates pain 7 of 10 and received an analgesic 15 minutes ago','A','Severe hyperkalemia with ECG changes can progress to lethal dysrhythmias. Light pink urine after TURP is expected, and the analgesic needs time to take effect.','Renal & Urinary','Management of Care'),
('Set05-RN-2','Reduction of Risk Potential','Acute kidney injury','single_best_answer','Which set of findings is most consistent with prerenal acute kidney injury?','BUN 48 mg/dL, creatinine 1.6 mg/dL, urine specific gravity 1.030, urine sodium low|BUN 30 mg/dL, creatinine 3.0 mg/dL, urine specific gravity 1.010, muddy brown casts|Bilateral hydronephrosis on ultrasound|Red blood cell casts and proteinuria','A','Prerenal AKI results from decreased renal perfusion. The kidneys conserve sodium and water, producing concentrated urine with low urine sodium and a BUN-to-creatinine ratio above 20:1. Muddy brown casts suggest acute tubular necrosis, hydronephrosis suggests postrenal obstruction, and RBC casts suggest glomerulonephritis.','Renal & Urinary','Adult Health'),
('Set05-RN-3','Reduction of Risk Potential','Urine output','single_best_answer','A 70-kg client in the ICU has had a total urine output of 180 mL over the past 6 hours. What should the nurse do?','Document the output as adequate|Notify the provider, because the output is below 0.5 mL/kg/hr|Irrigate the indwelling catheter without a prescription|Encourage the client to drink more coffee','B','The output is 30 mL/hr, or about 0.43 mL/kg/hr. Urine output below 0.5 mL/kg/hr for 6 hours meets criteria for oliguria and possible AKI, so the provider must be notified. The nurse should first confirm the catheter is not kinked or obstructed.','Renal & Urinary','Adult Health'),
('Set05-RN-4','Safety and Infection Control','AV fistula','single_best_answer','The nurse is caring for a client with a left forearm arteriovenous fistula. Which action by the assistive personnel requires the nurse to intervene?','Measuring blood pressure on the client''s left arm|Reporting that the client''s left hand feels cool and numb|Placing a sign at the bedside that says "No BP or needle sticks in left arm"|Helping the client wear loose-fitting sleeves','A','Blood pressure cuffs, venipuncture, and tight clothing on the fistula arm can damage or occlude the access. A cool, numb hand may indicate steal syndrome and should be reported.','Renal & Urinary','Safety & Infection Control'),
('Set05-RN-5','Pharmacological and Parenteral Therapies','Hemodialysis','single_best_answer','A client with a history of hypotension during hemodialysis is scheduled for treatment at 0900. Which scheduled 0800 medication should the nurse clarify with the provider before administering?','Sevelamer with breakfast|Amlodipine|Omeprazole|A multivitamin','B','Antihypertensives are often held before dialysis because fluid removal can cause hypotension. Water-soluble drugs may also be removed by dialysis and are timed afterward.','Renal & Urinary','Pharmacology'),
('Set05-RN-6','Reduction of Risk Potential','Peritoneal dialysis','single_best_answer','A client receiving peritoneal dialysis at home reports abdominal pain. The nurse notes the dialysate effluent is cloudy. Which complication does the nurse suspect?','Fluid overload|Peritonitis|Normal effluent|Hyperglycemia','B','Cloudy effluent with abdominal pain or fever indicates peritonitis, the most common serious complication of PD. The effluent should be sent for cell count and culture, and antibiotics are started.','Renal & Urinary','Adult Health'),
('Set05-RN-7','Reduction of Risk Potential','Peritoneal dialysis','single_best_answer','During peritoneal dialysis, the outflow of dialysate is slow and less than the amount instilled. What should the nurse do first?','Irrigate the catheter with 50 mL of sterile saline|Check the tubing for kinks, ensure the drainage bag is below the abdomen, and turn the client from side to side|Increase the dextrose concentration of the next exchange|Remove the catheter','B','Slow outflow is often caused by kinked tubing, bag position, constipation, or catheter position. Repositioning the client and checking the tubing are the first steps.','Renal & Urinary','Adult Health'),
('Set05-RN-8','Health Promotion and Maintenance','Renal diet','single_best_answer','The nurse is reviewing dietary teaching with a client receiving hemodialysis. Which meal choice indicates understanding?','Baked potato with cheese and a glass of orange juice|Grilled chicken, white rice, green beans, and an apple|Ham sandwich with pickles and a banana|Canned chili with a glass of milk','B','Clients on hemodialysis limit potassium, phosphorus, and sodium and need adequate high-quality protein. Potatoes, oranges, bananas, and dairy are high in potassium or phosphorus, and ham, pickles, and canned foods are high in sodium.','Renal & Urinary','Fundamentals'),
('Set05-RN-9','Pharmacological and Parenteral Therapies','Phosphate binders','single_best_answer','When should the nurse administer sevelamer to a client with chronic kidney disease?','With meals|At bedtime|On an empty stomach 2 hours before meals|Only when the phosphorus is above 10 mg/dL','A','Phosphate binders must be taken with meals so they bind dietary phosphorus in the GI tract and prevent absorption.','Renal & Urinary','Pharmacology'),
('Set05-RN-10','Pharmacological and Parenteral Therapies','Erythropoiesis-stimulating agents','single_best_answer','A client with chronic kidney disease is scheduled to receive epoetin alfa. Today''s hemoglobin is 12.3 g/dL, and BP is 162/94 mm Hg. What should the nurse do?','Administer the dose as prescribed|Hold the dose and notify the provider|Double the dose to prevent anemia|Administer the dose and recheck the hemoglobin next week','B','In CKD, ESAs are reduced or held when hemoglobin approaches or exceeds about 11 g/dL because higher levels increase the risk of stroke, thrombosis, and cardiovascular events. ESAs also raise BP.','Renal & Urinary','Pharmacology'),
('Set05-RN-11','Physiological Adaptation','Transplant rejection','multiple_response','A client received a kidney transplant 3 months ago. Which findings may indicate rejection? Select all that apply. ☐','Fever ☐|Decreased urine output ☐|Tenderness over the graft site ☐|Rising serum creatinine ☐|Weight gain and edema ☐|Increased urine output with normal creatinine ☐|New-onset hypertension','A,B,C,D,E,G','Rejection reduces graft function, causing oliguria, fluid retention, hypertension, and rising creatinine, often with fever and graft tenderness. Increased output with normal creatinine indicates good function.','Renal & Urinary','Adult Health'),
('Set05-RN-12','Pharmacological and Parenteral Therapies','Immunosuppressants','single_best_answer','A client is taking tacrolimus after a kidney transplant. Which client statement indicates a need for further teaching?','"I''ll take this medication for as long as I have the transplant."|"I''ll drink grapefruit juice every morning with my pills."|"I''ll avoid crowds and people who are sick."|"I''ll keep my appointments for blood level checks."','B','Grapefruit juice inhibits CYP3A4 and can raise tacrolimus to toxic levels. Lifelong immunosuppression, infection precautions, and level monitoring are correct.','Renal & Urinary','Pharmacology'),
('Set05-RN-13','Physiological Adaptation','Nephrotic syndrome','single_best_answer','Which combination of findings does the nurse expect in a client with nephrotic syndrome?','Frothy urine, generalized edema, serum albumin 2.1 g/dL, and elevated cholesterol|Cola-colored urine, hypertension, and recent strep throat|Flank pain, fever, and white blood cell casts|Polyuria with low urine specific gravity','A','Nephrotic syndrome is defined by heavy proteinuria (frothy urine), hypoalbuminemia, edema, and hyperlipidemia. Cola-colored urine with hypertension suggests glomerulonephritis, and flank pain with fever suggests pyelonephritis.','Renal & Urinary','Adult Health'),
('Set05-RN-14','Physiological Adaptation','Glomerulonephritis','single_best_answer','An 8-year-old has periorbital edema, dark tea-colored urine, and BP 138/90 mm Hg. Which information in the child''s history is most relevant?','A sore throat 2 weeks ago|A recent fall from a bicycle|Eating beets yesterday|A family history of asthma','A','Acute post-streptococcal glomerulonephritis typically follows group A strep pharyngitis or skin infection by 1–3 weeks. Immune complexes damage the glomeruli, causing hematuria, edema, and hypertension.','Renal & Urinary','Adult Health'),
('Set05-RN-15','Basic Care and Comfort','Urolithiasis','multiple_response','A client is admitted with renal colic from a ureteral stone. Which interventions should the nurse include? Select all that apply. ☐','Strain all urine ☐|Administer prescribed analgesics ☐|Encourage oral fluids unless contraindicated ☐|Encourage ambulation as tolerated ☐|Restrict fluids to 1,000 mL/day ☐|Maintain strict bed rest','A,B,C,D','Straining urine allows stone analysis, and pain control is a priority. Fluids and ambulation help move the stone. Fluid restriction and bed rest do not help stone passage.','Renal & Urinary','Adult Health'),
('Set05-RN-16','Reduction of Risk Potential','Continuous bladder irrigation','single_best_answer','A client is receiving continuous bladder irrigation after a TURP. Over 8 hours, 1,800 mL of irrigant was infused, and the total drainage in the collection bag is 2,300 mL. What is the client''s actual urine output for this period?','300 mL|500 mL|1,800 mL|2,300 mL','B','True urine output equals total drainage minus irrigant infused: 2,300 − 1,800 = 500 mL. If drainage is less than the amount infused, the catheter may be obstructed by clots.','Renal & Urinary','Adult Health'),
('Set05-RN-17','Physiological Adaptation','Pyelonephritis','single_best_answer','Which finding helps the nurse distinguish acute pyelonephritis from cystitis?','Urinary frequency|Burning on urination|Fever with costovertebral angle tenderness|Cloudy urine','C','Upper urinary tract infection causes systemic signs such as fever, chills, and flank or CVA tenderness. Frequency, dysuria, and cloudy urine occur in both.','Renal & Urinary','Adult Health'),
('Set05-RN-18','Safety and Infection Control','CAUTI prevention','multiple_response','Which actions reduce the risk of catheter-associated urinary tract infection? Select all that apply. ☐','Remove the catheter as soon as it is no longer needed ☐|Keep the drainage bag below the level of the bladder ☐|Maintain a closed drainage system ☐|Disconnect the catheter from the tubing to obtain a urine sample ☐|Irrigate the catheter routinely every shift ☐|Secure the catheter to the thigh to prevent movement','A,B,C,F','Minimizing catheter days, preventing backflow, maintaining a closed system, and securing the catheter reduce infection risk. Samples are taken from the sampling port, and routine irrigation breaks the closed system.','Renal & Urinary','Safety & Infection Control'),
('Set05-RN-19','Reduction of Risk Potential','Contrast-associated nephropathy','single_best_answer','A client with stage 3 chronic kidney disease is scheduled for a CT scan with IV contrast. Which action is most important before the procedure?','Restrict fluids for 12 hours before the scan|Review the client''s current eGFR/creatinine and plan for hydration as prescribed|Give a high-protein meal|Administer a potassium supplement Case study (use for RN Questions 20–25). A 58-year-old client with end-stage kidney disease receives hemodialysis every Monday, Wednesday, and Friday. The client missed Friday''s session because of a family emergency and arrives at the emergency department on Monday morning. Nurses'' notes, 0730: Reports generalized muscle weakness, tingling in the hands and around the mouth, and shortness of breath when lying down. Crackles in both lung bases. +2 pitting edema in the lower legs. Weight is 4.2 kg above the client''s documented dry weight. Anuric. Left forearm AV fistula with palpable thrill and audible bruit. Vital signs: T 98.2°F (36.8°C), HR 54/min and irregular, RR 24/min, BP 172/98 mm Hg, SpO2 91% on room air. 12-lead ECG: tall, peaked T waves, widened QRS complex, and flattened P waves. Laboratory results: potassium 7.2 mEq/L (3.5–5.0), sodium 133 mEq/L, BUN 110 mg/dL, creatinine 11.2 mg/dL, HCO3 16 mEq/L (22–26), phosphorus 7.8 mg/dL (2.5–4.5), calcium 7.9 mg/dL (8.6–10.2), hemoglobin 9.1 g/dL.','B','Reduced kidney function increases the risk of contrast-associated kidney injury. Baseline function is reviewed, and IV hydration is often prescribed. Nephrotoxic drugs and metformin may be held.','Renal & Urinary','Adult Health'),
('Set06-RN-1','Management of Care','Prioritization','single_best_answer','The nurse on a surgical unit receives report on four clients. Which client should the nurse assess first?','A client with suspected appendicitis whose severe pain suddenly subsided and who now has a rigid abdomen and temperature of 102°F (38.9°C)|A client with GERD who reports heartburn after breakfast|A client with a new colostomy who is asking about diet|A client with cirrhosis who is scheduled for paracentesis tomorrow','A','Sudden relief of appendicitis pain followed by abdominal rigidity and fever suggests perforation and peritonitis, which is a surgical emergency. The other clients are stable.','Gastrointestinal','Management of Care'),
('Set06-RN-2','Safety and Infection Control','Appendicitis','single_best_answer','A client is admitted with suspected acute appendicitis. Which prescription should the nurse question?','Keep NPO|Tap water enema|IV fluids at 125 mL/hr|IV morphine for pain','B','Enemas, laxatives, and heat to the abdomen can increase pressure on the appendix and cause rupture. Current evidence supports giving analgesics, which do not meaningfully delay diagnosis.','Gastrointestinal','Safety & Infection Control'),
('Set06-RN-3','Reduction of Risk Potential','NG tube placement','single_best_answer','The nurse has inserted a small-bore nasogastric feeding tube. Which method most reliably confirms placement before the first feeding?','Auscultating the epigastrium while injecting air|Radiographic (x-ray) confirmation|Asking the client whether they can speak|Placing the end of the tube in water to check for bubbles','B','An x-ray is the gold standard for confirming initial feeding tube placement. Aspirate pH of 5 or less supports gastric placement for ongoing checks. The air-bolus method is unreliable.','Gastrointestinal','Adult Health'),
('Set06-RN-4','Reduction of Risk Potential','Enteral feeding','single_best_answer','A client is receiving continuous enteral feeding through a nasogastric tube. Which observation requires the nurse to intervene?','The head of the bed is elevated to 35 degrees|The feeding bag is labeled with the date and time it was hung|The assistive personnel lowered the head of the bed flat for linen change without pausing the feeding|The tube''s external length matches the documented mark','C','Lying flat during feeding increases the risk of aspiration. The head of the bed should remain at 30–45 degrees, or the feeding should be paused if the client must lie flat briefly.','Gastrointestinal','Adult Health'),
('Set06-RN-5','Pharmacological and Parenteral Therapies','Parenteral nutrition','single_best_answer','A client''s parenteral nutrition (PN) bag is empty, and the pharmacy says the new bag will not be ready for 2 hours. What should the nurse do?','Hang 0.9% sodium chloride at the same rate|Hang 10% dextrose in water at the PN rate until the new bag arrives|Stop the infusion and flush the line|Double the rate of the new bag when it arrives','B','Abruptly stopping PN can cause rebound hypoglycemia because of high circulating insulin. D10W provides a similar dextrose concentration. Rates are never increased to catch up.','Gastrointestinal','Pharmacology'),
('Set06-RN-6','Physiological Adaptation','Refeeding syndrome','single_best_answer','A severely malnourished client started enteral nutrition 2 days ago. Which lab result is most important for the nurse to report?','Phosphorus 1.4 mg/dL|Sodium 138 mEq/L|Albumin 2.8 g/dL|Glucose 128 mg/dL','A','Refeeding syndrome causes intracellular shifts of phosphorus, potassium, and magnesium when nutrition resumes. Severe hypophosphatemia can cause heart failure, respiratory failure, and dysrhythmias. Nutrition is advanced slowly with electrolyte monitoring.','Gastrointestinal','Adult Health'),
('Set06-RN-7','Pharmacological and Parenteral Therapies','Hepatic encephalopathy','single_best_answer','A client with cirrhosis and hepatic encephalopathy is receiving lactulose. Which finding indicates the medication is effective?','One hard stool every 3 days|Two to three soft stools per day and improved mental status|Increased asterixis|Serum ammonia rising from 80 to 110 mcg/dL','B','Lactulose traps ammonia in the colon and removes it through stool. The goal is typically 2–3 soft stools daily with improved cognition. Worsening asterixis and a rising ammonia indicate progression.','Gastrointestinal','Pharmacology'),
('Set06-RN-8','Pharmacological and Parenteral Therapies','Esophageal varices','single_best_answer','A client with cirrhosis is vomiting large amounts of bright red blood. Which medication does the nurse anticipate?','Octreotide IV infusion|Oral propranolol|Ibuprofen|Oral lactulose','A','Octreotide reduces splanchnic blood flow and portal pressure during acute variceal bleeding. Antibiotic prophylaxis and urgent endoscopy with band ligation follow. Nonselective beta blockers are used for long-term prevention, not active bleeding.','Gastrointestinal','Pharmacology'),
('Set06-RN-9','Reduction of Risk Potential','Paracentesis','single_best_answer','The nurse is preparing a client for abdominal paracentesis. Which action is most important before the procedure?','Have the client void|Place the client in Trendelenburg position|Insert a nasogastric tube|Keep the client NPO for 12 hours','A','Emptying the bladder reduces the risk of puncturing it. The client sits upright or in high-Fowler''s position. After the procedure, the nurse monitors for hypotension caused by fluid shifts.','Gastrointestinal','Adult Health'),
('Set06-RN-10','Physiological Adaptation','Acute pancreatitis','multiple_response','Which findings does the nurse expect in a client with acute pancreatitis? Select all that apply. ☐','Severe epigastric pain radiating to the back ☐|Elevated serum lipase ☐|Bluish discoloration around the umbilicus ☐|Bluish discoloration of the flanks ☐|Serum calcium 7.6 mg/dL ☐|Pain relieved by lying flat','A,B,C,D,E','Pancreatitis causes epigastric pain radiating to the back and an elevated lipase. Cullen''s (periumbilical) and Grey Turner''s (flank) signs indicate retroperitoneal hemorrhage. Hypocalcemia results from fat saponification. Pain is often relieved by sitting up and leaning forward, not by lying flat.','Gastrointestinal','Adult Health'),
('Set06-RN-11','Physiological Adaptation','Cholecystitis','single_best_answer','Which finding supports a diagnosis of acute cholecystitis?','Pain in the right lower quadrant at McBurney''s point|Right upper quadrant pain after a fatty meal with a positive Murphy''s sign|Left lower quadrant pain relieved by bowel movements|Epigastric pain relieved by eating','B','Gallbladder inflammation causes RUQ pain after fatty meals, often radiating to the right shoulder. Murphy''s sign is inspiratory arrest during RUQ palpation. McBurney''s point pain suggests appendicitis.','Gastrointestinal','Adult Health'),
('Set06-RN-12','Safety and Infection Control','Hepatitis A','single_best_answer','The nurse is teaching a client diagnosed with hepatitis','Which client statement indicates a need for further teaching?|"I''ll wash my hands well after using the bathroom."|"I won''t prepare food for others while I''m contagious."|"It''s fine for my family to share my utensils and cups."|"My family members may need a vaccine or immune globulin."','C','Hepatitis A spreads by the fecal-oral route. Household contacts should not share utensils, and they may need post-exposure vaccination or immune globulin.','Gastrointestinal','Safety & Infection Control'),
('Set06-RN-14','Reduction of Risk Potential','Ostomy','single_best_answer','The nurse is assessing a client 12 hours after creation of an ileostomy. Which finding requires immediate action?','Stoma is pink and moist|Small amount of liquid output in the pouch|Stoma is dark purple to black|Mild edema of the stoma','C','A dusky, purple, or black stoma indicates compromised blood supply and necrosis, which requires immediate surgical evaluation. A pink, moist, slightly edematous stoma with liquid output is expected.','Gastrointestinal','Adult Health'),
('Set06-RN-15','Basic Care and Comfort','Diverticulitis','single_best_answer','A client is being treated at home for an acute episode of uncomplicated diverticulitis. Which diet does the nurse anticipate during the acute phase?','High-fiber diet with bran|Clear liquids, advancing to low-fiber foods as symptoms improve|High-fat diet|Regular diet with nuts and seeds','B','Bowel rest with clear liquids, then low-fiber foods, reduces inflammation during the acute phase. Once recovered, a high-fiber diet helps prevent recurrence. Current evidence does not require avoiding nuts and seeds long term.','Gastrointestinal','Adult Health'),
('Set06-RN-16','Safety and Infection Control','Clostridioides difficile','multiple_response','A client is diagnosed with Clostridioides difficile infection. Which actions should the nurse take? Select all that apply. ☐','Place the client on contact precautions ☐|Wear a gown and gloves when entering the room ☐|Wash hands with soap and water after care ☐|Clean the room with a sporicidal (bleach-based) disinfectant ☐|Use alcohol-based hand rub as the only hand hygiene ☐|Administer an antidiarrheal to stop the diarrhea','A,B,C,D','C. difficile spores are not killed by alcohol-based rubs, so soap and water and sporicidal cleaning are required. Antidiarrheals can trap toxins and increase the risk of toxic megacolon.','Gastrointestinal','Safety & Infection Control'),
('Set06-RN-17','Health Promotion and Maintenance','GERD','single_best_answer','The nurse is teaching a client with gastroesophageal reflux disease. Which client statement indicates a need for further teaching?','"I''ll raise the head of my bed on 6-inch blocks."|"I''ll lie down for a nap right after lunch."|"I''ll eat smaller meals."|"I''ll limit caffeine, alcohol, and chocolate."','B','Lying down within 2–3 hours after eating promotes reflux. Head-of-bed elevation, small meals, and avoiding trigger foods reduce symptoms.','Gastrointestinal','Fundamentals'),
('Set06-RN-18','Basic Care and Comfort','Dumping syndrome','single_best_answer','A client reports dizziness, sweating, and cramping 20 minutes after meals following a partial gastrectomy. Which instruction should the nurse provide?','"Drink plenty of fluids with each meal."|"Eat small, high-protein, low-carbohydrate meals and lie down briefly after eating."|"Eat three large meals high in simple sugars."|"Sit upright and walk right after meals."','B','Dumping syndrome results from rapid emptying of hypertonic food into the small intestine. Small meals, limited simple sugars, fluids between rather than with meals, and lying down after eating slow gastric emptying.','Gastrointestinal','Adult Health'),
('Set06-RN-19','Reduction of Risk Potential','Liver biopsy','single_best_answer','After a percutaneous liver biopsy, how should the nurse position the client?','On the left side|On the right side with a pillow under the costal margin|Prone|High-Fowler''s Case study (use for RN Questions 20–25). A 62-year-old client with osteoarthritis who takes ibuprofen 800 mg three times daily is brought to the emergency department by a spouse. The client had two black, tarry stools yesterday and vomited dark material that looked like coffee grounds this morning. Nurses'' notes, 1000: Anxious and pale. Skin cool and clammy. Reports epigastric pain rated 5/10 and lightheadedness when standing. Capillary refill 4 seconds. Abdomen soft and nondistended. Vital signs: T 97.8°F (36.6°C), HR 122/min, RR 24/min, BP 88/52 mm Hg (baseline 140/80), SpO2 95% on room air. Laboratory results: hemoglobin 7.2 g/dL (12–16), hematocrit 22% (36–48), BUN 42 mg/dL (7–20), creatinine 1.0 mg/dL, platelets 240,000/mm3, INR 1.1.','B','Lying on the right side applies pressure to the puncture site and reduces the risk of bleeding. The nurse monitors vital signs frequently for hemorrhage.','Gastrointestinal','Adult Health'),
('Set07-RN-1','Management of Care','Prioritization','single_best_answer','The nurse on an orthopedic unit receives report on four clients. Which client should the nurse assess first?','A client with a new long-leg cast who reports pain not relieved by IV morphine that worsens when the toes are moved|A client 1 day after total knee arthroplasty who rates pain 5/10|A client with gout who is requesting a lower-purine meal tray|A client with osteoporosis who has questions about calcium supplements','A','Pain out of proportion to the injury, unrelieved by opioids and worsened by passive stretch, suggests acute compartment syndrome. Permanent muscle and nerve damage can occur within hours.','Musculoskeletal','Management of Care'),
('Set07-RN-2','Physiological Adaptation','Compartment syndrome','single_best_answer','The nurse is monitoring a client with a tibial fracture for compartment syndrome. Which finding is the earliest indicator?','Absent pedal pulse|Pale, cold foot|Increasing pain with passive stretching of the toes|Inability to move the toes','C','Severe pain, especially with passive stretch, is the earliest and most reliable sign. Pulselessness, pallor, and paralysis are late signs that indicate advanced ischemia. The extremity is kept at heart level, not elevated above it, and the provider is notified immediately.','Musculoskeletal','Adult Health'),
('Set07-RN-3','Physiological Adaptation','Hip fracture','single_best_answer','An 82-year-old client fell at home and is brought to the emergency department. Which finding supports a suspected hip fracture?','Affected leg lengthened and internally rotated|Affected leg shortened and externally rotated|Bilateral lower leg edema|Pain in the lower back only','B','A displaced hip fracture typically causes shortening and external rotation of the affected leg, with groin or hip pain and inability to bear weight.','Musculoskeletal','Adult Health'),
('Set07-RN-4','Safety and Infection Control','Total hip arthroplasty','single_best_answer','A client had a total hip arthroplasty through a posterior approach 2 days ago. Which observation requires the nurse to intervene?','The client has an abduction pillow between the legs while in bed|The client is sitting in a low chair, bending forward to tie shoes|The client is using a raised toilet seat|The client is using a reacher to pick up items from the floor','B','After a posterior approach, the client avoids hip flexion beyond 90 degrees, crossing the legs, and internal rotation to prevent dislocation. Low chairs and bending forward exceed the flexion limit. Precautions vary by surgical approach and surgeon.','Musculoskeletal','Safety & Infection Control'),
('Set07-RN-5','Reduction of Risk Potential','Postoperative complications','single_best_answer','A client is 2 days postoperative after total knee arthroplasty. Which finding requires the nurse''s immediate action?','Incisional pain rated 4/10 after analgesic|Temperature of 99.5°F (37.5°C)|Sudden shortness of breath, chest pain, and HR 118/min|Moderate bruising around the knee','C','Sudden dyspnea, chest pain, and tachycardia after lower-extremity joint replacement suggest pulmonary embolism, which requires emergency intervention. Low-grade fever, bruising, and controlled pain are expected.','Musculoskeletal','Adult Health'),
('Set07-RN-6','Safety and Infection Control','Skeletal traction','single_best_answer','The nurse is caring for a client in skeletal traction. Which finding requires the nurse to intervene?','The weights are hanging freely|The client''s body is aligned with the line of pull|The traction weights are resting on the floor|The ropes move freely through the pulleys','C','Weights must hang freely to maintain continuous, effective traction. Weights on the floor eliminate the pull. The nurse never removes skeletal traction weights without a prescription.','Musculoskeletal','Safety & Infection Control'),
('Set07-RN-7','Safety and Infection Control','Pin site care','single_best_answer','The nurse is performing pin site care for a client with an external fixator. Which finding should the nurse report?','Small amount of clear serous drainage|Slight crusting at the pin sites|Thick yellow-green drainage with spreading redness|Mild tenderness during cleaning','C','Purulent drainage and spreading erythema indicate pin site infection, which can progress to osteomyelitis. Clear drainage, mild crusting, and slight tenderness are expected.','Musculoskeletal','Safety & Infection Control'),
('Set07-RN-8','Reduction of Risk Potential','Osteomyelitis','single_best_answer','A client is receiving a 6-week course of IV antibiotics for osteomyelitis. Which lab trend indicates a positive response to treatment?','Rising erythrocyte sedimentation rate and C-reactive protein|Declining erythrocyte sedimentation rate and C-reactive protein|Increasing white blood cell count|Rising serum creatinine','B','ESR and CRP are inflammatory markers used to monitor osteomyelitis. Declining values indicate a response. A rising creatinine suggests nephrotoxicity from antibiotics such as vancomycin.','Musculoskeletal','Adult Health'),
('Set07-RN-9','Pharmacological and Parenteral Therapies','Bisphosphonates','single_best_answer','The nurse is teaching a client who is starting alendronate for osteoporosis. Which instruction is correct?','"Take it at bedtime with a snack."|"Take it first thing in the morning with a full glass of plain water and remain upright for at least 30 minutes before eating."|"Take it with your calcium supplement and orange juice."|"Lie down for 30 minutes after taking it."','B','Alendronate is poorly absorbed and can cause esophagitis. It is taken on an empty stomach with plain water, and the client stays upright for at least 30 minutes before eating, drinking, or taking other medications.','Musculoskeletal','Pharmacology'),
('Set07-RN-10','Health Promotion and Maintenance','Osteoporosis risk','multiple_response','Which factors increase a client''s risk for osteoporosis? Select all that apply. ☐','Postmenopausal status ☐|Cigarette smoking ☐|Long-term corticosteroid therapy ☐|Sedentary lifestyle ☐|Regular weight-bearing exercise ☐|Excessive alcohol intake ☐|Low calcium and vitamin D intake','A,B,C,D,F,G','Estrogen loss, smoking, steroids, inactivity, alcohol, and low calcium and vitamin D reduce bone density. Weight-bearing exercise builds and maintains bone.','Musculoskeletal','Fundamentals'),
('Set07-RN-11','Health Promotion and Maintenance','Gout','single_best_answer','A client with gout asks which foods to limit. Which foods should the nurse identify?','Low-fat dairy products|Organ meats, shellfish, and beer|Fresh vegetables|Whole grains','B','Organ meats, shellfish, and beer are high in purines, which increase uric acid. High-fructose drinks should also be limited. Low-fat dairy may lower uric acid levels.','Musculoskeletal','Fundamentals'),
('Set07-RN-13','Pharmacological and Parenteral Therapies','Methotrexate','single_best_answer','The nurse is teaching a client with rheumatoid arthritis who is starting oral methotrexate. Which client statement indicates a need for further teaching?','"I''ll take my folic acid as prescribed."|"I''ll take my methotrexate every morning."|"I''ll avoid drinking alcohol."|"I''ll keep my appointments for blood tests."','B','For RA, methotrexate is taken once weekly. Daily dosing is a serious, potentially fatal error causing bone marrow suppression and toxicity. Folic acid, alcohol avoidance, contraception, and monitoring of the CBC and liver function are correct teaching.','Musculoskeletal','Pharmacology'),
('Set07-RN-14','Pharmacological and Parenteral Therapies','Biologic agents','single_best_answer','A client with rheumatoid arthritis is scheduled to begin adalimumab. Which test should the nurse verify has been completed before the first dose?','Tuberculosis screening|Hemoglobin A1C|Thyroid-stimulating hormone|Urine drug screen','A','TNF inhibitors can reactivate latent tuberculosis, so TB screening is required before therapy. Hepatitis B screening is also recommended. Live vaccines are avoided during treatment.','Musculoskeletal','Pharmacology'),
('Set07-RN-15','Basic Care and Comfort','Amputation','single_best_answer','A client is 3 days postoperative after a below-the-knee amputation. Which intervention helps prevent hip flexion contracture?','Keep a pillow under the residual limb at all times|Place the client prone for 20–30 minutes several times a day, if tolerated|Keep the head of the bed elevated 60 degrees continuously|Encourage the client to sit in a chair most of the day','B','Lying prone extends the hip and prevents flexion contracture. After the first 24–48 hours, the residual limb is not elevated on a pillow, and prolonged sitting is avoided.','Musculoskeletal','Adult Health'),
('Set07-RN-16','Safety and Infection Control','Crutch walking','single_best_answer','The nurse observes a client walking with axillary crutches. Which observation requires correction?','The crutch pads are 2–3 fingerbreadths below the axillae|The client is leaning on the axillary pads to support body weight|The elbows are flexed about 20–30 degrees|The client moves the crutches and the injured leg forward together','B','Weight is supported on the hands, not the axillae. Leaning on the pads can compress the brachial plexus and cause crutch palsy.','Musculoskeletal','Safety & Infection Control'),
('Set07-RN-17','Physiological Adaptation','Rhabdomyolysis','single_best_answer','A client was trapped under debris for several hours. The urine is dark reddish-brown, and the creatine kinase (CK) is 48,000 units/L. What is the nurse''s priority intervention?','Restrict fluids to prevent edema|Administer aggressive IV fluids as prescribed and monitor urine output|Encourage ambulation|Administer potassium supplements','B','Rhabdomyolysis releases myoglobin, which can cause acute kidney injury. Aggressive IV hydration maintains urine output and flushes myoglobin. Potassium is often elevated from muscle breakdown, so supplements are contraindicated.','Musculoskeletal','Adult Health'),
('Set07-RN-18','Health Promotion and Maintenance','Cast care','single_best_answer','The nurse is teaching a client with a new fiberglass arm cast. Which client statement indicates a need for further teaching?','"I''ll keep my arm elevated above my heart for the first couple of days."|"I''ll use a coat hanger to scratch under the cast if it itches."|"I''ll report any foul odor or warm spots on the cast."|"I''ll wiggle my fingers often."','B','Inserting objects under a cast can break the skin and cause infection. Elevation, finger movement, and reporting odor or warm spots (which may indicate infection or pressure injury) are correct.','Musculoskeletal','Fundamentals'),
('Set07-RN-19','Safety and Infection Control','Spinal surgery','single_best_answer','How should the nurse reposition a client after a lumbar spinal fusion?','Have the client twist at the waist to turn|Log-roll the client with assistance, keeping the spine aligned|Raise the head of the bed to 90 degrees before turning|Have the client use the overhead trapeze to pull up and turn Case study (use for RN Questions 20–25). A 24-year-old client sustained a closed fracture of the left femoral shaft in a motorcycle crash and is in skeletal traction awaiting surgical fixation. Nurses'' notes, day 2 (36 hours after injury), 0600: Client is newly restless and confused, asking "Where am I?" Reports difficulty breathing. Pinpoint reddish-purple spots noted across the upper chest, in both axillae, and on the conjunctivae. Left thigh is swollen, and pain at the fracture site is rated 5/10. Pin sites are clean with a small amount of clear, crusted drainage. Traction weights hang freely. Left pedal pulse is palpable, and toes are warm with brisk capillary refill. Vital signs: T 101.2°F (38.4°C), HR 124/min, RR 30/min, BP 118/70 mm Hg, SpO2 86% on room air. Laboratory results: platelets 98,000/mm3 (on admission: 240,000/mm3), hemoglobin 10.8 g/dL.','B','Log-rolling moves the head, shoulders, and hips as one unit to prevent twisting of the surgical site. A pillow between the knees helps maintain alignment.','Musculoskeletal','Safety & Infection Control'),
('Set08-RN-1','Management of Care','Prioritization','single_best_answer','The nurse on an oncology unit receives report on four clients. Which client should the nurse assess first?','A client 30 minutes into a packed red blood cell transfusion who reports new low back pain and chills|A client with sickle cell disease in pain crisis who received IV morphine 20 minutes ago|A client with iron deficiency anemia who has questions about iron supplements|A client receiving chemotherapy who reports mild nausea','A','Low back pain and chills during a transfusion suggest an acute hemolytic reaction, which can rapidly cause shock, DIC, and kidney failure. The morphine needs time to work, and the others are stable.','Hematologic','Management of Care'),
('Set08-RN-2','Pharmacological and Parenteral Therapies','Transfusion reaction','single_best_answer','Fifteen minutes into a unit of packed red blood cells, the client develops chills, a temperature increase from 98.6°F to 101°F (37°C to 38.3°C), and anxiety. What should the nurse do first?','Slow the transfusion and recheck vital signs in 15 minutes|Stop the transfusion and maintain IV access with 0.9% sodium chloride using new tubing|Administer acetaminophen and continue the transfusion|Flush the blood tubing with normal saline','B','With any suspected reaction, the nurse stops the transfusion immediately and keeps the IV open with saline through new tubing, so no more blood enters the client. The nurse then notifies the provider and blood bank and returns the bag and tubing.','Hematologic','Pharmacology'),
('Set08-RN-3','Pharmacological and Parenteral Therapies','Blood administration','multiple_response','Which actions are correct when administering packed red blood cells? Select all that apply. ☐','Verify the client and blood product with another licensed nurse at the bedside ☐|Prime the tubing with 0.9% sodium chloride ☐|Stay with the client for the first 15 minutes ☐|Use tubing with a blood filter ☐|Prime the tubing with 5% dextrose in water ☐|Complete the transfusion within 4 hours of spiking the bag ☐|Obtain baseline vital signs before starting','A,B,C,D,F,G','Two-person verification, saline priming, filtered tubing, baseline vital signs, close observation early (when severe reactions usually occur), and completion within 4 hours are standard. Dextrose causes hemolysis of red cells.','Hematologic','Pharmacology'),
('Set08-RN-4','Pharmacological and Parenteral Therapies','Heparin-induced thrombocytopenia','single_best_answer','A client has been receiving heparin for 7 days. The platelet count has dropped from 260,000 to 110,000/mm³, and a new DVT is found in the left leg. What does the nurse anticipate?','Increasing the heparin dose|Stopping all heparin and starting a non-heparin anticoagulant such as argatroban|Transfusing platelets|Switching to enoxaparin','B','A platelet drop of more than 50% 5–10 days after starting heparin, with new thrombosis, suggests heparin-induced thrombocytopenia. All heparin, including flushes and low-molecular-weight heparin, is stopped, and a direct thrombin inhibitor is started.','Hematologic','Pharmacology'),
('Set08-RN-5','Physiological Adaptation','Disseminated intravascular coagulation','single_best_answer','A client with septic shock develops oozing from IV sites. Which set of lab results supports disseminated intravascular coagulation?','Increased platelets, shortened PT, elevated fibrinogen|Decreased platelets, prolonged PT and aPTT, decreased fibrinogen, elevated D-dimer|Normal platelets, normal PT, normal D-dimer|Elevated hemoglobin, decreased D-dimer','B','DIC consumes clotting factors and platelets while activating fibrinolysis. This causes thrombocytopenia, prolonged clotting times, low fibrinogen, and elevated D-dimer. Treating the underlying cause is key.','Hematologic','Adult Health'),
('Set08-RN-6','Physiological Adaptation','Sickle cell crisis','multiple_response','Which interventions should the nurse include for a client admitted in vaso-occlusive sickle cell crisis? Select all that apply. ☐','IV fluids as prescribed ☐|Scheduled or patient-controlled opioid analgesia ☐|Oxygen if SpO2 is below the prescribed target ☐|Apply cold packs to painful joints ☐|Monitor for fever and signs of infection ☐|Encourage strict bed rest for several days','A,B,C,E','Hydration, aggressive pain control, oxygen for hypoxemia, and infection monitoring are core interventions. Cold causes vasoconstriction and increases sickling, and prolonged bed rest increases the risk of complications. Warm compresses may help.','Hematologic','Adult Health'),
('Set08-RN-7','Physiological Adaptation','Acute chest syndrome','single_best_answer','A client with sickle cell disease develops chest pain, fever, cough, and SpO2 of 89%. The chest x-ray shows a new infiltrate. What is the nurse''s priority?','Encourage oral fluids and reassess in 4 hours|Recognize acute chest syndrome and notify the provider immediately for urgent treatment|Discharge the client with oral antibiotics|Apply a cold compress to the chest','B','Acute chest syndrome is a leading cause of death in sickle cell disease and requires urgent oxygen, antibiotics, pain control, incentive spirometry, and possibly transfusion.','Hematologic','Adult Health'),
('Set08-RN-8','Pharmacological and Parenteral Therapies','Oral iron','single_best_answer','The nurse is teaching a client who is starting oral ferrous sulfate. Which instruction is correct?','"Take it with milk to reduce stomach upset."|"Take it with orange juice, and expect your stools to become dark green or black."|"Take it with an antacid."|"Stop taking it if your stools darken."','B','Vitamin C enhances iron absorption. Dark stools are expected. Milk, antacids, and calcium reduce absorption. If GI upset occurs, iron can be taken with a small amount of food.','Hematologic','Pharmacology'),
('Set08-RN-9','Physiological Adaptation','Pernicious anemia','single_best_answer','A client is diagnosed with pernicious anemia. Which statement by the client indicates understanding of the treatment?','"I''ll need vitamin B12 injections or high-dose supplements for the rest of my life."|"Eating more red meat will cure this."|"I''ll take iron pills for 3 months."|"I only need treatment until my energy improves."','A','Pernicious anemia results from a lack of intrinsic factor, so dietary B12 cannot be absorbed. Lifelong B12 replacement, by injection or high-dose oral or nasal forms, is needed to prevent anemia and neurological damage.','Hematologic','Adult Health'),
('Set08-RN-10','Safety and Infection Control','Neutropenic precautions','multiple_response','A client''s absolute neutrophil count is 400/mm³. Which interventions should the nurse implement? Select all that apply. ☐','Place the client in a private room ☐|Perform meticulous hand hygiene before and after contact ☐|Avoid rectal temperatures and suppositories ☐|Screen visitors for signs of illness ☐|Allow a visitor with a cold to visit if wearing a mask ☐|Monitor temperature closely and report fever promptly','A,B,C,D,F','Severe neutropenia (ANC below 500) greatly increases infection risk. Hand hygiene is most important. Rectal procedures can cause mucosal injury and infection, and ill visitors should not visit. Fever may be the only sign of infection.','Hematologic','Safety & Infection Control'),
('Set08-RN-11','Safety and Infection Control','Low platelets','single_best_answer','A client''s platelet count is 18,000/mm³. Which prescription should the nurse clarify with the provider?','Use an electric razor|Administer the influenza vaccine intramuscularly today|Use a soft-bristled toothbrush|Apply pressure to venipuncture sites for 5 minutes','B','IM injections can cause hematomas and bleeding when platelets are severely low. The other measures are appropriate bleeding precautions.','Hematologic','Safety & Infection Control'),
('Set08-RN-12','Pharmacological and Parenteral Therapies','Vesicant extravasation','single_best_answer','During a peripheral infusion of a vesicant chemotherapy drug, the client reports burning at the site, and the nurse notes swelling. What should the nurse do first?','Remove the IV catheter immediately|Stop the infusion|Apply warm compresses|Flush the line with normal saline','B','The infusion is stopped first. The catheter is left in place so residual drug can be aspirated and a prescribed antidote can be given if indicated. Warm or cold compresses depend on the specific agent, and flushing pushes more drug into the tissue.','Hematologic','Pharmacology'),
('Set08-RN-13','Reduction of Risk Potential','Tumor lysis syndrome','single_best_answer','A client with a high-grade lymphoma started chemotherapy 24 hours ago. Which lab pattern indicates tumor lysis syndrome?','Hypokalemia, hypophosphatemia, hypercalcemia|Hyperkalemia, hyperphosphatemia, hyperuricemia, hypocalcemia|Hyponatremia only|Normal electrolytes with elevated hemoglobin','B','Rapid tumor cell breakdown releases potassium, phosphate, and nucleic acids (converted to uric acid). Phosphate binds calcium, causing hypocalcemia. Prevention includes aggressive hydration and allopurinol or rasburicase.','Hematologic','Adult Health'),
('Set08-RN-14','Physiological Adaptation','Superior vena cava syndrome','single_best_answer','A client with lung cancer reports increasing shortness of breath and a feeling of fullness in the head. Which finding suggests superior vena cava syndrome?','Swelling of the face, neck, and arms with distended neck and chest veins|Bilateral ankle edema only|Hypotension with warm, flushed extremities|Severe low back pain','A','Tumor compression of the superior vena cava impairs venous return from the upper body, causing facial, neck, and arm edema with prominent veins. It is an oncologic emergency.','Hematologic','Adult Health'),
('Set08-RN-15','Health Promotion and Maintenance','External radiation','single_best_answer','The nurse is teaching a client receiving external beam radiation to the chest. Which client statement indicates a need for further teaching?','"I''ll wash the area gently with mild soap and lukewarm water."|"I''ll scrub off the markings on my skin after each treatment."|"I''ll avoid sun exposure to the treatment area."|"I''ll ask before using any lotion on the area."','B','Skin markings guide accurate radiation delivery and must not be removed. Gentle care, sun avoidance, and using only approved products protect the irradiated skin.','Hematologic','Fundamentals'),
('Set08-RN-16','Safety and Infection Control','Brachytherapy','single_best_answer','A client has a sealed radioactive cervical implant. The nurse finds the implant in the bed linens. What should the nurse do?','Pick it up with gloved hands and reinsert it|Use long-handled forceps to place it in the lead container in the room and notify radiation safety|Discard it in the biohazard container|Leave it in place and continue care','B','A dislodged source is never touched by hand. Long forceps and the lead container minimize exposure (time, distance, shielding). The nurse notifies the radiation safety officer and provider.','Hematologic','Safety & Infection Control'),
('Set08-RN-17','Pharmacological and Parenteral Therapies','Warfarin reversal','single_best_answer','A client taking warfarin is admitted with active GI bleeding and an INR of 8.9. Which treatment does the nurse anticipate?','Protamine sulfate|IV vitamin K and 4-factor prothrombin complex concentrate|Increased warfarin dose|Oral aspirin','B','Serious bleeding with a high INR requires rapid reversal with IV vitamin K and PCC (or plasma if PCC is unavailable). Protamine reverses heparin.','Hematologic','Pharmacology'),
('Set08-RN-18','Pharmacological and Parenteral Therapies','Direct oral anticoagulants','single_best_answer','A client with atrial fibrillation is prescribed apixaban. Which statement by the client indicates understanding?','"I''ll need weekly INR blood tests."|"I won''t stop taking it without talking to my provider, and I''ll report any unusual bleeding."|"I need to avoid all green vegetables."|"I can double my next dose if I miss one."','B','DOACs do not need routine INR monitoring or vitamin K restriction. Stopping abruptly increases stroke risk, and bleeding should be reported. Missed doses are handled per specific instructions; doubling is not recommended.','Hematologic','Pharmacology'),
('Set08-RN-19','Health Promotion and Maintenance','Cancer screening','single_best_answer','A 46-year-old client at average risk for colorectal cancer asks when screening should begin. What is the nurse''s best response?','"Screening begins at age 60."|"Current guidelines recommend starting screening at age 45."|"Screening is only needed if you have symptoms."|"You only need screening if a parent had colon cancer." Case study (use for RN Questions 20–25). A 54-year-old client with acute myeloid leukemia is on day 10 after induction chemotherapy. The client has a right upper arm peripherally inserted central catheter (PICC). Nurses'' notes, 2000: Client reports shaking chills and says, "I just don''t feel right." Skin warm and flushed. Redness and tenderness about 2 cm around the PICC insertion site, without drainage. Oral mucosa has several small ulcers. Scattered petechiae on both lower legs. Gums bled slightly during mouth care. Pale and reports fatigue. Vital signs: T 101.5°F (38.6°C), HR 118/min, RR 24/min, BP 96/58 mm Hg (baseline 124/76), SpO2 95% on room air. Laboratory results: WBC 0.6 × 10³/mm³, absolute neutrophil count (ANC) 200/mm³, hemoglobin 8.1 g/dL, platelets 22,000/mm³, lactate 2.8 mmol/L (0.5–2.0), creatinine 1.3 mg/dL (baseline 0.9).','B','U.S. guidelines (USPSTF and American Cancer Society) recommend starting colorectal cancer screening at age 45 for average-risk adults, using colonoscopy or other approved tests.','Hematologic','Fundamentals'),
('Set09-RN-1','Safety and Infection Control','Prioritization and isolation','single_best_answer','The charge nurse in the emergency department is reviewing the status of four clients. Which situation requires the nurse''s action first?','A client with an MRSA wound infection on contact precautions in a private room|A client with fever, cough, conjunctivitis, and a new blotchy rash seated in the waiting room|A client with HIV who is asking about medication refills|A client with Clostridioides difficile on contact precautions who is resting','B','Fever, cough, conjunctivitis, and a rash suggest measles, which is highly contagious by the airborne route. The client needs a mask and immediate placement in an airborne infection isolation room to protect others.','Immune','Safety & Infection Control'),
('Set09-RN-3','Safety and Infection Control','PPE donning','single_best_answer','The nurse is preparing to enter the room of a client who requires contact and droplet precautions. In what order should the nurse put on personal protective equipment?','Gloves, gown, mask, goggles|Gown, mask, goggles or face shield, gloves|Mask, gloves, gown, goggles|Goggles, gloves, mask, gown','B','CDC donning order is gown, mask or respirator, eye protection, then gloves, with gloves pulled over the gown cuffs. Doffing typically begins with gloves, the most contaminated item.','Immune','Safety & Infection Control'),
('Set09-RN-4','Safety and Infection Control','Needlestick injury','single_best_answer','A nurse sustains a needlestick from a used needle after giving an injection to a client with HIV. What should the nurse do first?','Report the injury to the employee health department|Wash the site thoroughly with soap and water|Squeeze the site to make it bleed|Apply bleach to the site','B','Immediate washing with soap and water is the first step. The nurse then reports the exposure right away, because HIV post-exposure prophylaxis is most effective when started as soon as possible, ideally within hours and no later than 72 hours. Squeezing and caustic agents are not recommended.','Immune','Safety & Infection Control'),
('Set09-RN-5','Physiological Adaptation','HIV','single_best_answer','A client with HIV has a CD4 count of 160 cells/mm³. Which prescription does the nurse anticipate in addition to antiretroviral therapy?','Trimethoprim-sulfamethoxazole for Pneumocystis pneumonia prophylaxis|Live varicella vaccine|Discontinuation of antiretroviral therapy|High-dose corticosteroids','A','A CD4 count below 200 defines AIDS and increases the risk of Pneumocystis jirovecii pneumonia, so prophylaxis with TMP-SMX is started. Live vaccines are contraindicated with severe immunosuppression.','Immune','Adult Health'),
('Set09-RN-6','Health Promotion and Maintenance','Antiretroviral therapy','single_best_answer','The nurse is teaching a client who is starting antiretroviral therapy. Which client statement indicates understanding?','"I can skip doses on weekends if I feel well."|"If I take my medicine every day and my viral load stays undetectable, I won''t transmit HIV to sexual partners."|"I can stop the medication once my CD4 count is normal."|"Missing doses won''t affect whether the medication works."','B','Consistent daily adherence maintains viral suppression, prevents resistance, and means the client cannot sexually transmit HIV (undetectable = untransmittable). Therapy is lifelong.','Immune','Fundamentals'),
('Set09-RN-7','Physiological Adaptation','Systemic lupus erythematosus','single_best_answer','A client with systemic lupus erythematosus reports new swelling of the ankles and foamy urine. What does the nurse suspect?','Lupus nephritis|Expected medication side effect|Dehydration|Raynaud''s phenomenon','A','Foamy urine (proteinuria) and edema suggest lupus nephritis, a serious complication that can lead to kidney failure. Urinalysis and renal function tests are needed.','Immune','Adult Health'),
('Set09-RN-8','Pharmacological and Parenteral Therapies','Hydroxychloroquine','single_best_answer','A client with lupus is starting hydroxychloroquine. Which instruction should the nurse include?','"Have regular eye exams while taking this medication."|"Take it with grapefruit juice."|"Expect your urine to turn orange."|"Stop the medication if you feel better."','A','Hydroxychloroquine can cause retinal toxicity. A baseline eye exam and periodic screening are recommended.','Immune','Pharmacology'),
('Set09-RN-9','Safety and Infection Control','Latex allergy','single_best_answer','A client scheduled for surgery reports allergies to bananas, avocados, and kiwi. What should the nurse do?','Document the food allergies only|Notify the surgical team of a possible latex allergy and plan for a latex-free environment|Give a test dose of latex|No action is needed','B','These foods share proteins with natural rubber latex (latex-fruit syndrome). The client may be latex-sensitive, so the team should use a latex-free environment.','Immune','Safety & Infection Control'),
('Set09-RN-10','Health Promotion and Maintenance','Epinephrine auto-injector','single_best_answer','The nurse is teaching a client with a severe peanut allergy how to use an epinephrine auto-injector. Which instruction is correct?','"Inject into your upper arm muscle."|"Press the injector firmly against the outer thigh, even through clothing, hold it in place as directed, then call 911."|"Use it only if taking an antihistamine doesn''t work."|"After using it, you don''t need further medical care."','B','Epinephrine is injected into the anterolateral thigh and can be given through clothing. It is the first-line treatment for anaphylaxis. Emergency care is still needed because symptoms can recur.','Immune','Fundamentals'),
('Set09-RN-11','Pharmacological and Parenteral Therapies','Vaccines','single_best_answer','A client receiving chemotherapy for breast cancer is due for several vaccines. Which vaccine should the nurse question?','Inactivated influenza vaccine|Measles, mumps, and rubella (MMR) vaccine|Pneumococcal conjugate vaccine|Tetanus, diphtheria, and pertussis (Tdap) vaccine','B','MMR is a live attenuated vaccine and is contraindicated in immunocompromised clients and during pregnancy. Inactivated vaccines are generally safe, though response may be reduced.','Immune','Pharmacology'),
('Set09-RN-12','Management of Care','Sepsis bundle','multiple_response','A client meets criteria for sepsis with a lactate of 4.6 mmol/L and BP 84/48 mm Hg. Which actions are part of the initial sepsis bundle? Select all that apply. ☐','Measure a lactate level ☐|Obtain blood cultures before antibiotics ☐|Administer broad-spectrum antibiotics ☐|Give 30 mL/kg of IV crystalloid ☐|Start a vasopressor if hypotension persists during or after fluid resuscitation ☐|Wait for culture results before starting antibiotics','A,B,C,D,E','The Surviving Sepsis Campaign hour-1 bundle includes lactate, cultures, broad-spectrum antibiotics, 30 mL/kg crystalloid for hypotension or lactate of 4 or higher, and vasopressors to maintain MAP of at least 65 mm Hg. Delaying antibiotics increases mortality.','Immune','Management of Care'),
('Set09-RN-13','Pharmacological and Parenteral Therapies','Septic shock','single_best_answer','A client in septic shock remains hypotensive after adequate fluid resuscitation. Norepinephrine is started. Which goal is appropriate?','MAP of 65 mm Hg or higher|Systolic BP above 180 mm Hg|HR above 120/min|Urine output of 10 mL/hr','A','A MAP of at least 65 mm Hg maintains organ perfusion in septic shock. Adequate urine output (at least 0.5 mL/kg/hr) and falling lactate also indicate improved perfusion.','Immune','Pharmacology'),
('Set09-RN-14','Health Promotion and Maintenance','Lyme disease','single_best_answer','A client asks how to remove a tick found on the leg after hiking. Which instruction is correct?','"Burn it off with a match."|"Grasp the tick close to the skin with fine-tipped tweezers and pull upward with steady, even pressure."|"Cover it with petroleum jelly and wait for it to fall off."|"Twist it quickly while squeezing its body."','B','Steady removal with tweezers reduces the chance of leaving mouthparts behind. The client should clean the area and watch for an expanding "bull''s-eye" rash (erythema migrans), fever, or joint pain.','Immune','Fundamentals'),
('Set09-RN-15','Safety and Infection Control','Herpes zoster','single_best_answer','A client with localized herpes zoster (shingles) is admitted. Which staff member should not be assigned to this client?','A nurse who had chickenpox as a child|A pregnant nurse who has never had chickenpox or the varicella vaccine|A nurse who received the varicella vaccine|A nurse who had shingles last year','B','Contact with zoster lesions can transmit varicella-zoster virus to people who are not immune. Varicella in pregnancy can cause severe maternal and fetal complications.','Immune','Safety & Infection Control'),
('Set09-RN-16','Pharmacological and Parenteral Therapies','Vancomycin','single_best_answer','During an IV vancomycin infusion, the client develops flushing and a red rash on the face, neck, and upper chest. BP is stable, and there is no respiratory distress. What should the nurse do?','Continue the infusion at the same rate|Stop or slow the infusion and notify the provider, anticipating a slower infusion rate and possibly an antihistamine|Administer epinephrine IM|Discontinue vancomycin permanently','B','Vancomycin infusion reaction (formerly "red man syndrome") is related to rapid infusion, not true allergy. It is managed by slowing the rate (over at least 60 minutes) and giving antihistamines. The client''s stable BP and breathing distinguish it from anaphylaxis.','Immune','Pharmacology'),
('Set09-RN-17','Pharmacological and Parenteral Therapies','Aminoglycosides','single_best_answer','A client is receiving IV gentamicin. Which finding should the nurse report to the provider?','Ringing in the ears|Improved urinary symptoms|Mild injection-site tenderness|Creatinine of 0.8 mg/dL','A','Aminoglycosides are ototoxic and nephrotoxic. Tinnitus or hearing loss indicates ototoxicity. Drug levels and renal function are monitored.','Immune','Pharmacology'),
('Set09-RN-18','Safety and Infection Control','Hand hygiene','single_best_answer','In which situation must the nurse wash hands with soap and water rather than use an alcohol-based hand rub?','Before taking a blood pressure|After caring for a client with norovirus|After touching a clean over-bed table|Before entering a room on contact precautions for MRSA','B','Soap and water are needed when hands are visibly soiled and after caring for clients with spore-forming or alcohol-resistant organisms such as C. difficile and norovirus. Alcohol rub is appropriate for most other situations.','Immune','Safety & Infection Control'),
('Set09-RN-19','Pharmacological and Parenteral Therapies','Medication allergies','single_best_answer','A client is prescribed amoxicillin-clavulanate. During the medication history, the client reports developing hives the last time they took amoxicillin. What should the nurse do?','Administer the medication with diphenhydramine|Hold the medication and clarify the prescription with the provider|Give a half dose to test for a reaction|Administer the medication, since hives are a minor reaction Case study (use for RN Questions 20–25). A 34-year-old client is in the emergency department being treated for acute pyelonephritis. The client reports no known drug allergies. The first dose of IV ceftriaxone was started 10 minutes ago. Nurses'' notes, 1510: Client suddenly reports itching all over, a tight throat, and feeling faint. The nurse notes widespread raised, red hives; swelling of the lips and eyelids; a hoarse voice; and audible expiratory wheezing. The client is anxious and says, "I feel like something terrible is happening." Vital signs: T 100.4°F (38°C), HR 128/min, RR 28/min, BP 78/42 mm Hg (on arrival: 122/76), SpO2 89% on room air.','B','Amoxicillin-clavulanate contains amoxicillin. A prior hypersensitivity reaction means the drug should be held and the provider notified to select an alternative. The allergy and reaction type are documented.','Immune','Pharmacology'),
('Set10-RN-1','Management of Care','Prioritization','single_best_answer','The nurse in the emergency department receives four clients. Which client should the nurse assess first?','A client with burns to the face who has singed nasal hair and a hoarse voice|A client with a stage 2 pressure injury on the sacrum|A client with cellulitis of the lower leg and a temperature of 100.6°F (38.1°C)|A client with a psoriasis flare requesting topical medication','A','Facial burns, singed nasal hair, and hoarseness indicate inhalation injury with airway edema, which can quickly progress to complete obstruction. Early intubation may be needed.','Integumentary','Management of Care'),
('Set10-RN-2','Physiological Adaptation','Carbon monoxide poisoning','single_best_answer','A client rescued from an enclosed burning building has a headache and confusion. The pulse oximeter reads 99%. What should the nurse do?','Document the normal oxygen saturation|Apply 100% oxygen by nonrebreather mask and anticipate a carboxyhemoglobin level|Apply oxygen at 2 L/min by nasal cannula|Encourage deep breathing and reassess in 1 hour','B','Standard pulse oximetry cannot tell carboxyhemoglobin from oxyhemoglobin, so SpO2 can be falsely normal. The treatment is 100% oxygen, which shortens the half-life of carbon monoxide. Hyperbaric therapy may be considered in severe cases.','Integumentary','Adult Health'),
('Set10-RN-3','Physiological Adaptation','Rule of nines','single_best_answer','Using the rule of nines, what is the total body surface area burned in an adult with burns to the entire right arm and the entire anterior trunk?','18%|27%|36%|45%','B','Each entire arm is 9% and the anterior trunk is 18%, so 9% + 18% = 27%. Superficial (first-degree) burns are not included in TBSA calculations.','Integumentary','Adult Health'),
('Set10-RN-4','Physiological Adaptation','Burn depth','single_best_answer','Which description is consistent with a full-thickness burn?','Red, painful, blanches with pressure, no blisters|Moist, red, blistered, and very painful|White or charred, dry, leathery, and painless to touch|Pink with mild peeling after 3 days','C','Full-thickness burns destroy the epidermis, dermis, and nerve endings, leaving dry, leathery eschar with little pain. They usually require grafting. Moist, blistered, painful burns are partial-thickness.','Integumentary','Adult Health'),
('Set10-RN-5','Reduction of Risk Potential','Circumferential burns','single_best_answer','A client has circumferential full-thickness burns of the left arm. Which finding requires immediate action?','Edema of the arm|Diminishing radial pulse by Doppler and increasing numbness of the fingers|Pain at the edges of the burn|Dry, leathery appearance of the burn','B','Inelastic eschar combined with swelling can compress vessels and nerves, similar to compartment syndrome. Loss of pulses or sensation requires emergency escharotomy. Edema and leathery eschar are expected.','Integumentary','Adult Health'),
('Set10-RN-6','Reduction of Risk Potential','Burn shock','single_best_answer','Which laboratory findings does the nurse expect during the first 24 hours after a major burn?','Decreased hematocrit and hypokalemia|Elevated hematocrit and hyperkalemia|Normal hematocrit and hypernatremia|Decreased hematocrit and hypercalcemia','B','During the emergent phase, capillary leak shifts plasma out of the vessels, which concentrates the blood and raises hematocrit. Cell destruction releases potassium. Later, hypokalemia often develops as fluid shifts back and diuresis begins.','Integumentary','Adult Health'),
('Set10-RN-7','Pharmacological and Parenteral Therapies','Topical burn agents','single_best_answer','A client with partial-thickness burns is prescribed silver sulfadiazine cream. Which information in the client''s history should the nurse report before applying it?','Allergy to sulfonamide antibiotics|Allergy to shellfish|History of hypertension|Seasonal allergies','A','Silver sulfadiazine is a sulfonamide and may cause reactions in clients with sulfa allergy. It can also cause transient leukopenia.','Integumentary','Pharmacology'),
('Set10-RN-8','Basic Care and Comfort','Burn nutrition','single_best_answer','Which dietary plan does the nurse anticipate for a client recovering from a major burn?','Low-calorie, low-protein diet|High-calorie, high-protein diet with supplemental vitamins and minerals|Clear liquids only for 2 weeks|Low-fat, low-sodium diet only','B','Major burns cause a hypermetabolic state with greatly increased calorie and protein needs for wound healing and immune function. Early enteral feeding is preferred.','Integumentary','Adult Health'),
('Set10-RN-9','Physiological Adaptation','Electrical burns','single_best_answer','A client sustained a high-voltage electrical injury. There are small entry and exit wounds on the hand and foot. What is the nurse''s priority?','Dress the small wounds|Place the client on continuous cardiac monitoring|Calculate the TBSA using the rule of nines|Apply cool compresses to the wounds','B','Electrical current can cause dysrhythmias and cardiac arrest. Small skin wounds often hide extensive deep tissue damage, which can release myoglobin and cause kidney injury, so urine color is also monitored.','Integumentary','Adult Health'),
('Set10-RN-10','Safety and Infection Control','Chemical burns','single_best_answer','A worker is brought in with dry lime powder on the arms. What should the nurse do first?','Immediately flush the arms with water|Brush off the dry powder, then flush with large amounts of water|Apply a neutralizing acid|Cover the arms with dry dressings','B','Dry chemicals are brushed off first, because water can activate some powders. The area is then irrigated with copious water. Neutralizing agents can cause heat injury.','Integumentary','Safety & Infection Control'),
('Set10-RN-11','Reduction of Risk Potential','Pressure injury staging','single_best_answer','The nurse assesses a sacral wound with full-thickness tissue loss. Subcutaneous fat is visible, but no bone, tendon, or muscle is exposed. How should the nurse document this wound?','Stage 1|Stage 2|Stage 3|Stage 4','C','Stage 3 involves full-thickness skin loss with visible fat. Stage 4 exposes bone, tendon, or muscle. Stage 2 is partial-thickness, and wounds obscured by slough or eschar are unstageable.','Integumentary','Adult Health'),
('Set10-RN-12','Reduction of Risk Potential','Braden scale','single_best_answer','Four clients have the following Braden Scale scores. Which client is at highest risk for developing a pressure injury?','Score of 20|Score of 17|Score of 13|Score of 9','D','Lower Braden scores indicate higher risk. A score of 9 or less is very high risk, and scores of 18 or less generally indicate risk.','Integumentary','Adult Health'),
('Set10-RN-13','Basic Care and Comfort','Pressure injury prevention','multiple_response','Which interventions help prevent pressure injuries in an immobile client? Select all that apply. ☐','Reposition at least every 2 hours ☐|Keep the head of the bed at 30 degrees or lower when possible ☐|Manage incontinence promptly ☐|Use a pressure-redistribution mattress ☐|Massage reddened bony prominences ☐|Use a donut-shaped cushion when sitting','A,B,C,D','Repositioning, limiting head elevation (to reduce shear), moisture control, and pressure-redistribution surfaces reduce risk. Massaging reddened areas damages tissue, and donut cushions concentrate pressure around the edges.','Integumentary','Adult Health'),
('Set10-RN-14','Reduction of Risk Potential','Negative-pressure wound therapy','single_best_answer','A client''s negative-pressure wound therapy device has been off for 3 hours because of a power issue. What should the nurse do?','Restart the device over the existing foam dressing|Remove the foam dressing and apply a moist saline dressing, then notify the provider|Leave the foam dressing in place until the next scheduled change|Increase the suction pressure when restarting','B','If the device is off for more than about 2 hours (per manufacturer and facility policy), the foam can trap drainage and bacteria. It is replaced with a moist dressing, and the provider is notified.','Integumentary','Adult Health'),
('Set10-RN-15','Physiological Adaptation','Cellulitis','single_best_answer','A client is admitted with cellulitis of the lower leg. Which action helps the nurse monitor the response to treatment?','Apply a tight compression bandage|Outline the border of redness with a skin marker and note the date and time|Keep the leg in a dependent position|Massage the area to reduce swelling','B','Marking the border allows objective tracking of spread or improvement. The leg is elevated to reduce swelling.','Integumentary','Adult Health'),
('Set10-RN-16','Physiological Adaptation','Necrotizing fasciitis','single_best_answer','A client with a small leg wound reports severe pain far out of proportion to the appearance of the wound. The redness has spread rapidly over 3 hours, and the client is tachycardic and febrile. What does the nurse suspect?','Simple cellulitis|Necrotizing fasciitis requiring emergency surgical evaluation|Contact dermatitis|Normal healing','B','Pain out of proportion, rapid spread, and systemic toxicity suggest necrotizing soft tissue infection. It requires emergency surgical debridement and broad-spectrum antibiotics.','Integumentary','Adult Health'),
('Set10-RN-17','Pharmacological and Parenteral Therapies','Stevens-Johnson syndrome','single_best_answer','Two weeks after starting lamotrigine, a client develops fever, painful red skin with blisters, and sores in the mouth and eyes. What should the nurse anticipate?','Continuing the medication with an antihistamine|Stopping the medication and providing care similar to that for a major burn|Applying hydrocortisone cream and discharging the client|Doubling the dose','B','These findings suggest Stevens-Johnson syndrome or toxic epidermal necrolysis, a severe drug reaction. The causative drug is stopped immediately, and care focuses on fluid management, wound care, pain control, and infection prevention, often in a burn unit.','Integumentary','Pharmacology'),
('Set10-RN-18','Pharmacological and Parenteral Therapies','Isotretinoin','single_best_answer','A 19-year-old female client is starting isotretinoin for severe acne. Which statement indicates understanding?','"I can get pregnant while taking this if I stop the medicine as soon as I find out."|"I''ll use two forms of birth control and have regular pregnancy tests as required by the program."|"I''ll take extra vitamin A supplements."|"I can donate blood while taking this."','B','Isotretinoin is highly teratogenic. The iPLEDGE program requires contraception and pregnancy testing. Vitamin A supplements increase toxicity, and blood donation is prohibited during treatment and for 1 month after.','Integumentary','Pharmacology'),
('Set10-RN-19','Pharmacological and Parenteral Therapies','Topical corticosteroids','single_best_answer','The nurse is teaching a client how to apply a high-potency topical corticosteroid for psoriasis plaques. Which instruction is correct?','"Apply a thick layer to the face daily."|"Apply a thin layer only to the affected areas as prescribed."|"Cover the area with plastic wrap overnight unless your provider tells you not to."|"Use it on all skin to prevent new plaques." Case study (use for RN Questions 20–25). A 42-year-old client weighing 80 kg is brought to the emergency department 1 hour after being burned in a house fire. There was no enclosed-space smoke exposure; the client was burned while pulling a family member from a burning porch. Nurses'' notes, 0300: Alert and oriented. Voice clear; no soot in the mouth or nose; no singed nasal hair. Burns cover the entire anterior trunk and the anterior surfaces of both legs. Some areas are red, blistered, moist, and very painful; other areas are white, dry, leathery, and painless to touch. Pedal pulses palpable bilaterally. Pain rated 9/10. Indwelling urinary catheter inserted: 15 mL of dark amber urine in the first hour. Vital signs: T 97.0°F (36.1°C), HR 128/min, RR 24/min, BP 96/60 mm Hg, SpO2 97% on room air. Laboratory results: hematocrit 54% (37–47), potassium 5.4 mEq/L (3.5–5.0), sodium 134 mEq/L (135–145).','B','Thin application to affected areas reduces the risk of skin atrophy and systemic absorption. High-potency steroids are avoided on the face and skin folds. Occlusion increases absorption and is used only if prescribed.','Integumentary','Pharmacology'),
('Set11-RN-1','Management of Care','Prioritization','single_best_answer','The nurse reviews morning lab results for four clients. Which client should the nurse assess first?','A client with potassium 2.9 mEq/L who has new frequent PVCs on the monitor|A client with sodium 133 mEq/L who is alert and asymptomatic|A client with total calcium 8.4 mg/dL and low albumin|A client with magnesium 1.6 mg/dL who is receiving oral supplements','A','Hypokalemia with ventricular ectopy increases the risk of lethal dysrhythmias. The other values are mildly abnormal, and those clients are stable. A low total calcium with low albumin may reflect a normal ionized calcium.','Integrated','Management of Care'),
('Set11-RN-3','Pharmacological and Parenteral Therapies','IV fluids and ICP','single_best_answer','A client with a traumatic brain injury and cerebral edema has a new IV fluid prescription. Which solution should the nurse question?','0.9% sodium chloride|0.45% sodium chloride|3% sodium chloride|Lactated Ringer''s','B','Hypotonic fluids move water into brain cells and worsen cerebral edema and ICP. Isotonic or hypertonic solutions are used.','Integrated','Pharmacology'),
('Set11-RN-4','Pharmacological and Parenteral Therapies','IV potassium','single_best_answer','Which potassium chloride prescription should the nurse question?','Potassium chloride 10 mEq in 100 mL over 1 hour via infusion pump|Potassium chloride 20 mEq IV push over 2 minutes|Potassium chloride 20 mEq orally twice daily|Potassium chloride 20 mEq added to 1,000 mL 0.9% sodium chloride at 100 mL/hr','B','IV potassium is never given by IV push because it can cause cardiac arrest. It is diluted and infused by pump, typically no faster than 10 mEq/hr through a peripheral line unless a policy allows faster central-line rates with cardiac monitoring.','Integrated','Pharmacology'),
('Set11-RN-5','Reduction of Risk Potential','Hypokalemia','single_best_answer','Which ECG changes are consistent with hypokalemia?','Tall, peaked T waves and widened QRS|Flattened T waves and prominent U waves|Shortened QT interval|ST elevation in leads II, III, and aVF','B','Hypokalemia causes flattened or inverted T waves, ST depression, and U waves. Peaked T waves indicate hyperkalemia, and a short QT suggests hypercalcemia.','Integrated','Adult Health'),
('Set11-RN-6','Physiological Adaptation','Hyponatremia correction','single_best_answer','A client with severe symptomatic hyponatremia is receiving 3% sodium chloride. The sodium was 114 mEq/L at 0800 and is 128 mEq/L at 2000. What should the nurse do?','Continue the infusion, since the sodium is still below normal|Notify the provider immediately because the sodium is rising too quickly|Increase the infusion rate|Encourage the client to drink more water','B','Correcting chronic hyponatremia too quickly can cause osmotic demyelination syndrome. The rise is generally limited to about 8–10 mEq/L in 24 hours. A 14 mEq/L rise in 12 hours exceeds safe limits.','Integrated','Adult Health'),
('Set11-RN-7','Physiological Adaptation','Hypernatremia','single_best_answer','An older adult with dementia who has had poor fluid intake has a serum sodium of 156 mEq/L. Which findings does the nurse expect?','Weight gain and bounding pulses|Thirst, dry mucous membranes, restlessness, and confusion|Muscle cramps and U waves|Positive Trousseau''s sign','B','Hypernatremia draws water out of brain cells, causing thirst, dry mucosa, irritability, confusion, and in severe cases seizures. Older adults may have a blunted thirst response.','Integrated','Adult Health'),
('Set11-RN-8','Physiological Adaptation','Hypocalcemia','multiple_response','Which findings are consistent with hypocalcemia? Select all that apply. ☐','Carpal spasm when a BP cuff is inflated (Trousseau''s sign) ☐|Facial twitching when the facial nerve is tapped (Chvostek''s sign) ☐|Numbness and tingling around the mouth ☐|Muscle cramps ☐|Diminished deep tendon reflexes ☐|Prolonged QT interval','A,B,C,D,F','Low calcium increases neuromuscular excitability, causing tetany, paresthesias, cramps, hyperactive reflexes, and a prolonged QT. It can progress to laryngospasm and seizures. Diminished reflexes suggest hypercalcemia or hypermagnesemia.','Integrated','Adult Health'),
('Set11-RN-9','Physiological Adaptation','Hypercalcemia','single_best_answer','A client with metastatic breast cancer has a serum calcium of 13.2 mg/dL. Which findings does the nurse expect?','Tetany and seizures|Muscle weakness, constipation, confusion, and polyuria|Hyperactive reflexes|Diarrhea and positive Chvostek''s sign','B','Hypercalcemia depresses neuromuscular activity (weakness, hyporeflexia, lethargy) and causes constipation, polyuria, kidney stones, and a shortened QT. Treatment includes IV fluids and medications such as bisphosphonates.','Integrated','Adult Health'),
('Set11-RN-10','Reduction of Risk Potential','Hypomagnesemia','single_best_answer','A client with alcohol use disorder has persistent hypokalemia despite several days of potassium replacement. Which lab value should the nurse check?','Magnesium|Sodium|Chloride|Albumin','A','Hypomagnesemia causes renal potassium wasting and makes hypokalemia difficult to correct. Magnesium must be replaced first. Low magnesium also increases the risk of torsades de pointes.','Integrated','Adult Health'),
('Set11-RN-11','Physiological Adaptation','Hypermagnesemia','single_best_answer','A client with chronic kidney disease has been taking magnesium-containing laxatives. The serum magnesium is 5.8 mg/dL. Which finding does the nurse expect?','Hyperactive deep tendon reflexes|Diminished deep tendon reflexes and respiratory depression|Tetany|Tachycardia and hypertension','B','Magnesium depresses neuromuscular transmission, causing hyporeflexia, lethargy, hypotension, bradycardia, and respiratory depression. IV calcium gluconate is the antidote.','Integrated','Adult Health'),
('Set11-RN-12','Reduction of Risk Potential','Phosphorus and calcium','single_best_answer','A client with chronic kidney disease has a serum phosphorus of 7.9 mg/dL. Which additional lab finding does the nurse expect?','Elevated calcium|Decreased calcium|Elevated sodium|Decreased potassium','B','Phosphorus and calcium have an inverse relationship. High phosphorus binds calcium and lowers the serum level, which contributes to renal bone disease.','Integrated','Adult Health'),
('Set11-RN-13','Reduction of Risk Potential','Arterial blood gases','single_best_answer','A client with severe diarrhea for 4 days has the following ABG: pH 7.30, PaCO2 30 mm Hg, HCO3 15 mEq/L. How should the nurse interpret this?','Uncompensated respiratory acidosis|Partially compensated metabolic acidosis|Fully compensated metabolic alkalosis|Partially compensated respiratory alkalosis','B','The low pH and low HCO3 indicate metabolic acidosis from bicarbonate loss in stool. The low PaCO2 shows respiratory compensation that has not normalized the pH.','Integrated','Adult Health'),
('Set11-RN-14','Physiological Adaptation','Metabolic alkalosis','multiple_response','Which conditions increase a client''s risk for metabolic alkalosis? Select all that apply. ☐','Prolonged vomiting ☐|Continuous nasogastric suctioning ☐|Loop diuretic therapy ☐|Excessive use of antacids ☐|Severe diarrhea ☐|Diabetic ketoacidosis','A,B,C,D','Loss of gastric acid, diuretic-induced chloride and potassium loss, and excess base intake cause metabolic alkalosis. Diarrhea and DKA cause metabolic acidosis.','Integrated','Adult Health'),
('Set11-RN-15','Physiological Adaptation','Fluid volume excess','multiple_response','Which findings indicate fluid volume excess? Select all that apply. ☐','Bounding pulses ☐|Jugular venous distention ☐|Crackles in the lungs ☐|Weight gain of 2 kg in 2 days ☐|Weak, thready pulse ☐|Elevated hematocrit','A,B,C,D','Excess fluid causes bounding pulses, JVD, pulmonary crackles, rapid weight gain, and edema. Hemodilution lowers hematocrit. A weak pulse and elevated hematocrit suggest fluid volume deficit.','Integrated','Adult Health'),
('Set11-RN-16','Reduction of Risk Potential','Dehydration in older adults','single_best_answer','Which is the most accurate indicator of fluid balance changes in an older adult?','Skin turgor on the back of the hand|Daily weight trends|Reported thirst|Moisture of the axillae','B','Acute weight changes reflect fluid shifts most accurately. Skin turgor is unreliable in older adults because of lost elasticity, and thirst is often diminished.','Integrated','Adult Health'),
('Set11-RN-17','Reduction of Risk Potential','Daily weight','single_best_answer','A client with heart failure weighed 72.0 kg yesterday and 74.0 kg today, using the same scale and conditions. How much fluid has the client most likely retained?','About 0.5 L|About 1 L|About 2 L|About 4 L','C','1 kg of body weight is roughly equal to 1 L of fluid. A 2-kg overnight gain represents about 2 L of retained fluid and should be reported.','Integrated','Adult Health'),
('Set11-RN-18','Reduction of Risk Potential','IV infiltration','single_best_answer','The IV site of a client receiving 0.9% sodium chloride is swollen, cool, and pale, and the infusion is running slowly. What should the nurse do first?','Flush the catheter forcefully to restore flow|Stop the infusion|Apply a warm compress and continue the infusion|Increase the infusion rate','B','Swelling, coolness, and pallor indicate infiltration. The nurse stops the infusion first, then removes the catheter, elevates the extremity, and documents. Compress choice depends on the infusate.','Integrated','Adult Health'),
('Set11-RN-19','Pharmacological and Parenteral Therapies','Transfusion-associated circulatory overload','single_best_answer','An 84-year-old client with heart failure is receiving a second unit of packed red blood cells. The client develops dyspnea, crackles, BP 168/96 mm Hg, and distended neck veins. What should the nurse do first?','Increase the transfusion rate to finish quickly|Stop the transfusion and sit the client upright|Lay the client flat|Administer an antihistamine and continue Case study (use for RN Questions 20–25). A 78-year-old client with heart failure takes furosemide 40 mg daily and digoxin 0.125 mg daily. The client has had nausea and vomiting for 3 days from viral gastroenteritis but kept taking the furosemide. The client is admitted from the emergency department. Nurses'' notes, 1100: Reports weakness, dizziness when standing, and leg cramps. Dry mucous membranes. Abdomen mildly distended with hypoactive bowel sounds. Voided 150 mL of dark amber urine since arrival 4 hours ago. Respirations shallow. Cardiac monitor shows sinus tachycardia with frequent premature ventricular contractions (PVCs) and prominent U waves. Vital signs: T 98.8°F (37.1°C). Lying: BP 108/64 mm Hg, HR 102/min. Standing: BP 86/50 mm Hg, HR 124/min, client reports near-fainting. RR 12/min. SpO2 95% on room air. Laboratory results: sodium 136 mEq/L, potassium 2.6 mEq/L (3.5–5.0), chloride 88 mEq/L (98–106), magnesium 1.4 mg/dL (1.7–2.2), BUN 38 mg/dL, creatinine 1.3 mg/dL (baseline 0.9). Arterial blood gas: pH 7.50, PaCO2 46 mm Hg, HCO3 34 mEq/L.','B','These findings indicate transfusion-associated circulatory overload. Stopping the transfusion and sitting the client upright reduce venous return and improve breathing. Oxygen and a diuretic are typically prescribed next.','Integrated','Pharmacology'),
('Set12-RN-1','Management of Care','Prioritization','single_best_answer','The nurse on a labor and delivery unit receives report on four clients. Which client should the nurse assess first?','A client in active labor on oxytocin whose fetal heart rate tracing shows recurrent late decelerations|A client 1 day postpartum whose fundus is firm at the umbilicus|A client at 32 weeks'' gestation who reports a mild backache|A newborn with bluish hands and feet 1 hour after birth','A','Recurrent late decelerations indicate uteroplacental insufficiency and possible fetal hypoxia, especially during oxytocin infusion. The other findings are expected.','Maternal & Newborn','Management of Care'),
('Set12-RN-2','Reduction of Risk Potential','Late decelerations','multiple_response','A laboring client receiving oxytocin has recurrent late decelerations. Which actions should the nurse take? Select all that apply. ☐','Stop the oxytocin infusion ☐|Reposition the client onto her side ☐|Increase the IV fluid rate as prescribed or per protocol ☐|Notify the provider ☐|Increase the oxytocin rate to speed delivery ☐|Place the client flat on her back','A,B,C,D','Intrauterine resuscitation includes stopping oxytocin, lateral positioning to improve placental perfusion, an IV fluid bolus, and provider notification. Oxygen may be given per facility protocol. Supine positioning compresses the vena cava and reduces placental blood flow.','Maternal & Newborn','Adult Health'),
('Set12-RN-4','Physiological Adaptation','Umbilical cord prolapse','single_best_answer','After the membranes rupture, the nurse sees the umbilical cord protruding from the vagina. What should the nurse do first?','Push the cord back into the vagina|Insert a gloved hand into the vagina, lift the presenting part off the cord, and call for help|Place the client in high-Fowler''s position|Apply dry gauze to the cord','B','Relieving pressure on the cord restores fetal blood flow. The nurse maintains this position while the client is placed in knee-chest or Trendelenburg position and prepared for emergency cesarean birth. The cord is never pushed back, and exposed cord is covered with sterile saline-moistened gauze.','Maternal & Newborn','Adult Health'),
('Set12-RN-5','Pharmacological and Parenteral Therapies','Preeclampsia','single_best_answer','A client at 36 weeks'' gestation has BP 164/112 mm Hg, a severe headache, and blurred vision. Magnesium sulfate is prescribed. The client asks why. What is the nurse''s best response?','"It will lower your blood pressure."|"It helps prevent seizures."|"It will stop your labor."|"It speeds up your baby''s lung development."','B','Magnesium sulfate is given to prevent eclamptic seizures. Antihypertensives such as labetalol, hydralazine, or nifedipine are used to lower BP, and corticosteroids promote fetal lung maturity.','Maternal & Newborn','Pharmacology'),
('Set12-RN-6','Pharmacological and Parenteral Therapies','Magnesium toxicity','single_best_answer','A client receiving magnesium sulfate has RR 10/min, absent patellar reflexes, and urine output of 20 mL/hr. What should the nurse do first?','Continue the infusion and recheck in 1 hour|Stop the magnesium infusion|Administer calcium gluconate without a prescription|Increase the infusion rate','B','Respiratory depression, absent reflexes, and oliguria indicate magnesium toxicity. The nurse stops the infusion first, notifies the provider, and prepares calcium gluconate, the antidote.','Maternal & Newborn','Pharmacology'),
('Set12-RN-7','Safety and Infection Control','Placenta previa','single_best_answer','A client at 33 weeks'' gestation arrives with painless, bright red vaginal bleeding. Which action should the nurse avoid?','Applying the external fetal monitor|Performing a digital vaginal exam|Starting an IV line|Estimating the amount of blood loss','B','Painless bright red bleeding suggests placenta previa. A digital vaginal exam can cause severe hemorrhage and is avoided until previa is ruled out by ultrasound.','Maternal & Newborn','Safety & Infection Control'),
('Set12-RN-8','Physiological Adaptation','Placental abruption','single_best_answer','Which finding is most consistent with placental abruption?','Painless, bright red bleeding with a soft uterus|Sudden abdominal pain with a rigid, board-like uterus and dark red bleeding|Irregular painless contractions|Clear fluid leaking from the vagina','B','Placental abruption causes pain, uterine tenderness and rigidity, and dark bleeding, which may be concealed. Abruption can lead to fetal distress, hemorrhagic shock, and DIC.','Maternal & Newborn','Adult Health'),
('Set12-RN-9','Pharmacological and Parenteral Therapies','Rh immune globulin','single_best_answer','An Rh-negative postpartum client gave birth to an Rh-positive newborn. The client''s indirect Coombs test is negative. What does the nurse anticipate?','No treatment is needed|Administering Rh(D) immune globulin within 72 hours of birth|Administering Rh immune globulin to the newborn|Administering the rubella vaccine instead','B','Rh immune globulin prevents maternal sensitization to Rh-positive fetal blood cells. A negative indirect Coombs test confirms the client is not already sensitized. It is given to the mother, not the newborn.','Maternal & Newborn','Pharmacology'),
('Set12-RN-10','Pharmacological and Parenteral Therapies','Oxytocin','single_best_answer','A client receiving an oxytocin infusion for labor induction has had 7 contractions in 10 minutes. The fetal heart rate is 140/min with moderate variability. What should the nurse do first?','Increase the oxytocin rate|Stop or reduce the oxytocin infusion per protocol|Encourage the client to push|Document the findings as expected','B','More than 5 contractions in 10 minutes (averaged over 30 minutes) is tachysystole, which reduces placental perfusion. Oxytocin is stopped or reduced per protocol, followed by lateral positioning, IV fluids, and provider notification.','Maternal & Newborn','Pharmacology'),
('Set12-RN-11','Reduction of Risk Potential','Infant of a diabetic mother','single_best_answer','A newborn''s mother has poorly controlled gestational diabetes. Which assessment is most important in the first hours after birth?','Hearing screening|Blood glucose monitoring|Hip examination|Head circumference only','B','Maternal hyperglycemia stimulates fetal insulin production. After birth, the maternal glucose supply stops while insulin remains high, putting the newborn at risk for hypoglycemia.','Maternal & Newborn','Adult Health'),
('Set12-RN-12','Pharmacological and Parenteral Therapies','Ectopic pregnancy','single_best_answer','A client with an unruptured ectopic pregnancy is being treated with methotrexate. Which client statement indicates a need for further teaching?','"I''ll avoid alcohol while being treated."|"I''ll keep taking my prenatal vitamins with folic acid."|"I''ll return for follow-up blood tests."|"I''ll call if I have sudden severe abdominal or shoulder pain."','B','Methotrexate is a folic acid antagonist, so folic acid supplements reduce its effectiveness. Sudden severe pain or shoulder pain may indicate rupture.','Maternal & Newborn','Pharmacology'),
('Set12-RN-13','Physiological Adaptation','Postpartum infection','single_best_answer','A client is 3 days postpartum after a cesarean birth. Which findings suggest endometritis?','Lochia serosa and a firm fundus|Temperature of 101.4°F (38.6°C), uterine tenderness, and foul-smelling lochia|Afterpains during breastfeeding|Breast fullness','B','Fever after the first 24 hours, uterine tenderness, and foul lochia indicate uterine infection, which is more common after cesarean birth.','Maternal & Newborn','Adult Health'),
('Set12-RN-14','Health Promotion and Maintenance','Apgar score','single_best_answer','At 1 minute after birth, a newborn has HR 110/min, slow and irregular respirations, some flexion of the extremities, a grimace with stimulation, and a pink body with blue extremities. What is the Apgar score?','4|6|8|10','B','HR over 100 = 2, slow/irregular respirations = 1, some flexion = 1, grimace = 1, acrocyanosis = 1, for a total of 6. Scores of 7–10 are reassuring, 4–6 need some intervention, and 0–3 need resuscitation.','Maternal & Newborn','Fundamentals'),
('Set12-RN-15','Pharmacological and Parenteral Therapies','Newborn vitamin K','single_best_answer','A parent asks why the newborn needs a vitamin K injection. What is the nurse''s best response?','"It prevents eye infections."|"Newborns don''t yet have the gut bacteria that make vitamin K, so it helps prevent serious bleeding."|"It prevents jaundice."|"It boosts the immune system."','B','Newborns have a sterile gut and low vitamin K stores. The injection prevents vitamin K deficiency bleeding. Erythromycin ointment prevents eye infections.','Maternal & Newborn','Pharmacology'),
('Set12-RN-16','Reduction of Risk Potential','Neonatal jaundice','single_best_answer','Which finding in a newborn requires prompt reporting to the provider?','Jaundice first noticed at 60 hours of age|Jaundice first noticed at 18 hours of age|Milia on the nose|Mongolian spots on the lower back','B','Jaundice in the first 24 hours is pathological and suggests hemolysis, such as ABO or Rh incompatibility. Physiological jaundice appears after 24 hours. Milia and dermal melanocytosis are normal.','Maternal & Newborn','Adult Health'),
('Set12-RN-17','Physiological Adaptation','Neonatal opioid withdrawal','multiple_response','A newborn''s mother used opioids during pregnancy. Which findings suggest neonatal abstinence syndrome? Select all that apply. ☐','High-pitched cry ☐|Tremors ☐|Poor feeding ☐|Frequent sneezing and yawning ☐|Loose stools ☐|Sleeping 4 hours after each feeding','A,B,C,D,E','Opioid withdrawal causes CNS irritability, GI dysfunction, and autonomic signs. Care emphasizes a low-stimulation environment, swaddling, feeding on demand, and parental involvement (the Eat, Sleep, Console approach). Long, restful sleep is not a sign of withdrawal.','Maternal & Newborn','Adult Health'),
('Set12-RN-18','Health Promotion and Maintenance','Breastfeeding','single_best_answer','Which finding best indicates that a 6-day-old breastfed newborn is getting enough milk?','The newborn feeds every 5–6 hours|Six or more wet diapers and at least three yellow stools per day|The newborn cries after every feeding|The mother''s breasts never feel full','B','By day 5–6, adequate intake is shown by at least 6 wet diapers and several yellow, seedy stools per day, audible swallowing, and weight gain. Newborns typically feed 8–12 times in 24 hours.','Maternal & Newborn','Fundamentals'),
('Set12-RN-19','Psychosocial Integrity','Postpartum mood disorders','single_best_answer','Which postpartum client requires immediate intervention?','A client on day 3 who cries easily and feels overwhelmed|A client at 2 weeks who says she hears voices telling her the baby is evil|A client on day 4 who reports trouble sleeping because of night feedings|A client at 1 week who says she misses being pregnant Case study (use for RN Questions 20–25). A 32-year-old client, now gravida 4 para 4, gave birth vaginally 45 minutes ago to a 4,200-g (9 lb 4 oz) newborn after an 18-hour labor augmented with oxytocin. The placenta delivered intact. The oxytocin infusion was stopped after delivery of the placenta. The client has initiated breastfeeding. Nurses'' notes, 1545: The client reports feeling dizzy and "a gush of blood." Perineal pad saturated in 15 minutes with several large clots. Fundus boggy, 2 cm above the umbilicus, and deviated to the right. Bladder palpable above the symphysis; the client has not voided since delivery. Skin pale and cool. Quantitative blood loss since birth: 950 mL. Vital signs: HR 118/min, BP 92/58 mm Hg (1 hour ago: 124/78), RR 22/min, SpO2 97% on room air, T 98.8°F (37.1°C). History: no hypertension, no asthma. Blood type O positive.','B','Hallucinations and delusions about the infant indicate postpartum psychosis, a psychiatric emergency with risk of harm to mother and baby. Tearfulness in the first 2 weeks is typical of postpartum blues.','Maternal & Newborn','Mental Health')
) x(src,client_need,topic,item_type,stem,opts,keys,rationale,body_system,discipline) loop
 qid:=md5('rnmaster-'||lower(r.src))::uuid; qvid:=md5('rnmaster-v-'||lower(r.src))::uuid;
 insert into public.questions(id,slug,lifecycle_status,current_version) values(qid,'rnmaster-'||lower(r.src),'pilot',1) on conflict(slug) do update set updated_at=now() returning id into qid;
 keyarr:=string_to_array(r.keys,',');
 insert into public.question_versions(id,question_id,version,stem,item_type,exam_tracks,subject,topic,client_need,difficulty,rationale_correct,rationale_distractors,memory_rule,source_note,validation_status,professional_role_focus,track_rationale,body_system,discipline,source_id,response_config,scoring_method)
 values(qvid,qid,1,r.stem,r.item_type,array['rn'],r.client_need,r.topic,r.client_need,'medium',r.rationale,'Each distractor must be evaluated against the clinical task and source rationale.','Identify the task, interpret the cues, and compare every option with the safest evidence-based RN response.','User-provided NCLEX-RN Master Edition; loaded as PILOT pending clinical/editorial validation. Not human or psychometrically validated.','pilot','Entry-level RN clinical judgment.','NCLEX-RN',r.body_system,r.discipline,'RNMaster-'||r.src,'{}'::jsonb,case when r.item_type='multiple_response' then 'plus_minus' else 'zero_one' end)
 on conflict(question_id,version) do update set stem=excluded.stem,item_type=excluded.item_type,source_id=excluded.source_id,validation_status='pilot' returning id into qvid;
 delete from public.question_options where question_version_id=qvid; n:=0;
 for optrec in select unnest(string_to_array(r.opts,'|')) as txt loop n:=n+1; insert into public.question_options(question_version_id,option_key,option_text,is_correct,rationale,display_order) values(qvid,chr(96+n),optrec.txt,(upper(chr(96+n))=any(keyarr)),case when upper(chr(96+n))=any(keyarr) then r.rationale else null end,n); end loop;
 select count(*) filter(where is_correct) into kc from public.question_options where question_version_id=qvid;
 if (r.item_type='single_best_answer' and kc<>1) or (r.item_type='multiple_response' and kc<2) then raise exception 'Key integrity failed %',r.src; end if;
 update public.question_versions set key_consistency_status='pass',key_consistency_checked_at=now(),key_consistency_notes='Source key/options passed deterministic consistency validation; clinical review pending.' where id=qvid;
end loop;
end $$;
commit;